INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_355694aa63c80b', 'subj_phys', 'calculus-mechanics', 'Mechanics with calculus', 'v = \frac{dx}{dt}, \quad a = \frac{dv}{dt}, \quad W = \int F\,dx, \quad J = \int F\,dt, \quad F = -\frac{dU}{dx}', 'Velocity and acceleration as derivatives, work and impulse as integrals, and force from potential energy.', '[{"symbol":"J","meaning":"impulse","unit":"N·s"},{"symbol":"U","meaning":"potential energy","unit":"J"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_42fcc261971536', 'subj_phys', 'calculus-rotation', 'Rotation and mass distributions with calculus', 'x_{cm} = \frac{1}{M}\int x\,dm, \quad I = \int r^2\,dm, \quad \vec\tau = \vec r \times \vec F, \quad \vec L = \vec r \times \vec p', 'Center of mass and rotational inertia of continuous objects, and torque and angular momentum as cross products.', '[{"symbol":"dm","meaning":"mass element","unit":"kg"}]', 'published');

-- Lesson: calc-angular-momentum-conservation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_39e49c0dbbc367', 'calc-angular-momentum-conservation', 'Conservation of angular momentum', 'Apply angular momentum conservation to collisions between particles and rotating objects, and compare with energy losses.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_602a16982e935d', 'les_39e49c0dbbc367', 1, 'Identify when angular momentum about a pivot is conserved even though linear momentum isn''t.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d5ad69532cffa1', 'les_39e49c0dbbc367', 2, 'Solve particle–rod collisions with L = mvr⊥ and L = Iω.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_685964466bdde2', 'les_39e49c0dbbc367', 3, 'Compute kinetic energy lost in rotational collisions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_602a16982e935d', 'les_39e49c0dbbc367', 'learn', 1, 'definition', '{"term":"Conservation about a pivot","body":"If the net external torque about a point is zero, $\\vec L$ about that point is conserved. In a collision with a rod on a fixed pivot, the pivot exerts a force, so linear momentum isn''t conserved; but that force has no torque about the pivot, so angular momentum about the pivot is."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d5ad69532cffa1', 'les_39e49c0dbbc367', 'learn', 2, 'worked_example', '{"title":"A 0.05 kg lump of clay at 10 m/s hits the free end of a 0.6 kg, 1 m rod pivoted at its other end, perpendicular, and sticks","steps":[{"latex":"L_i = mvL = 0.05(10)(1) = 0.5\\ \\text{kg·m}^2/\\text{s}","explanation":""},{"latex":"I_f = \\tfrac13(0.6)(1^2) + 0.05(1^2)","explanation":"Rod about its end, plus the clay as a point mass."},{"latex":"I_f = 0.25\\ \\text{kg·m}^2","explanation":""},{"latex":"\\omega = \\tfrac{0.5}{0.25} = 2\\ \\text{rad/s}","explanation":""},{"latex":"K: 2.5\\ \\text{J} \\to \\tfrac12(0.25)(4) = 0.5\\ \\text{J}","explanation":"80% of the kinetic energy is lost: perfectly inelastic."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_685964466bdde2', 'les_39e49c0dbbc367', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Batters and tennis players aim for the sweet spot, where the impact sends no jolt to the hands; spacecraft docking maneuvers must conserve the combined angular momentum."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_602a16982e935d', 'les_39e49c0dbbc367', 1, 'practice', 'numeric', 2, 'A 0.1 kg ball at 6 m/s hits a door (I = 2 kg·m²) perpendicular, 0.8 m from the hinge, and stops dead. Find the door''s ω.', '{"answer":0.24,"unit":"rad/s"}', '[]', '$\frac{0.1(6)(0.8)}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d5ad69532cffa1', 'les_39e49c0dbbc367', 2, 'practice', 'numeric', 3, 'A 2 kg disk (R = 0.5 m) spins at 4 rad/s. A 0.5 kg ring of radius 0.5 m drops onto it concentrically. Find the final ω, to two decimal places.', '{"answer":2.67,"tolerance":0.01,"unit":"rad/s"}', '[]', '$I_1 = 0.25$, $I_2 = 0.125$; $\omega = \frac{1}{0.375}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_685964466bdde2', 'les_39e49c0dbbc367', 3, 'practice', 'multiple_choice', 2, 'When clay hits a pivoted rod, which is conserved about the pivot?', '{"choices":["linear momentum","angular momentum","kinetic energy","all three"],"answer":1}', '[]', 'The pivot force has no torque about the pivot.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_14d3e0e99bcb6b', 'les_39e49c0dbbc367', 4, 'review', 'multiple_choice', 3, 'A planet''s angular momentum about its star is conserved because gravity…', '{"choices":["is weak","points along r, so r × F = 0","is conservative","acts at a distance"],"answer":1}', '[]', 'A central force exerts no torque.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_39e49c0dbbc367', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_39e49c0dbbc367', (SELECT id FROM formulas WHERE slug = 'calculus-rotation'), 1);

-- Lesson: calc-angular-momentum
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6731c6390f66d3', 'calc-angular-momentum', 'Angular momentum and angular impulse', 'Define angular momentum L = r × p for particles, connect torque to its rate of change, τ = dL/dt, and compute angular impulse as ∫τ dt.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_997afd066f596d', 'les_6731c6390f66d3', 1, 'Compute L = r × p for a particle and L = Iω for a rigid body.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b8e725b08e8b32', 'les_6731c6390f66d3', 2, 'Use τ_net = dL/dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_55e512e0219ddc', 'les_6731c6390f66d3', 3, 'Compute angular impulse ∫τ dt = ΔL.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_997afd066f596d', 'les_6731c6390f66d3', 'learn', 1, 'definition', '{"term":"Definitions","body":"For a particle, $\\vec L = \\vec r\\times\\vec p$, so $L_z = m(xv_y - yv_x)$. For a rigid body rotating about a fixed axis, $L = I\\omega$. Differentiating, $\\frac{d\\vec L}{dt} = \\vec r\\times\\vec F = \\vec\\tau$, because $\\frac{d\\vec r}{dt}\\times\\vec p = \\vec v\\times m\\vec v = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b8e725b08e8b32', 'les_6731c6390f66d3', 'learn', 2, 'worked_example', '{"title":"A 2 kg particle at r = (3, 0) m with velocity (0, 4) m/s","steps":[{"latex":"L_z = 2[(3)(4) - (0)(0)] = 24\\ \\text{kg·m}^2/\\text{s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_55e512e0219ddc', 'les_6731c6390f66d3', 'learn', 3, 'worked_example', '{"title":"A wheel''s angular momentum is L(t) = 2t³ kg·m²/s","steps":[{"latex":"\\tau = \\tfrac{dL}{dt} = 6t^2","explanation":""},{"latex":"\\tau(2) = 24\\ \\text{N·m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9aa3c478372c27', 'les_6731c6390f66d3', 'learn', 4, 'definition', '{"term":"Angular impulse","body":"$\\int_{t_1}^{t_2}\\tau\\,dt = \\Delta L$: the area under a torque–time graph."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c149d7db236e0', 'les_6731c6390f66d3', 'learn', 5, 'callout', '{"tone":"note","title":"Straight-line motion","body":"A particle moving in a straight line at constant velocity has constant angular momentum about any point, because no torque acts on it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_daff39914bef15', 'les_6731c6390f66d3', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Reaction wheels in satellites trade angular momentum with the craft to point telescopes precisely."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_997afd066f596d', 'les_6731c6390f66d3', 1, 'practice', 'numeric', 2, 'A torque τ(t) = 3t² N·m acts on a wheel from rest (I = 0.5 kg·m²) for 2 s. Find ω afterward.', '{"answer":16,"unit":"rad/s"}', '[]', '$\Delta L = t^3 = 8$, so $\omega = \frac{8}{0.5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b8e725b08e8b32', 'les_6731c6390f66d3', 2, 'practice', 'numeric', 2, 'A 0.5 kg particle at r = (0, 2) m moves with v = (3, 0) m/s. Find L_z.', '{"answer":-3,"unit":"kg·m²/s"}', '[]', '$0.5[0 - (2)(3)]$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_55e512e0219ddc', 'les_6731c6390f66d3', 3, 'practice', 'multiple_choice', 2, 'A particle moves in a straight line at constant velocity. Its angular momentum about a point off the line…', '{"choices":["is zero","is constant and nonzero","increases","decreases"],"answer":1}', '[]', 'No torque, so constant: $L = mvr_\perp$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9aa3c478372c27', 'les_6731c6390f66d3', 4, 'review', 'multiple_choice', 3, 'τ = dL/dt is the rotational analog of…', '{"choices":["W = Fd","F = dp/dt","p = mv","K = ½mv²"],"answer":1}', '[]', 'Newton''s second law in momentum form.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6731c6390f66d3', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_6731c6390f66d3', (SELECT id FROM formulas WHERE slug = 'calculus-rotation'), 1);

-- Lesson: calc-center-of-mass
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_604d79ad83a8b6', 'calc-center-of-mass', 'Systems and center of mass', 'Find the center of mass of continuous objects by integration using linear density, and connect it to the motion of systems.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_debe8b6670b97b', 'les_604d79ad83a8b6', 1, 'Use linear density λ = dm/dx to find total mass M = ∫λ dx.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9df55d698c7f88', 'les_604d79ad83a8b6', 2, 'Compute x_cm = (1/M)∫x dm for rods with varying density.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e07f9474cfea4e', 'les_604d79ad83a8b6', 3, 'Explain why Σ F_ext = M a_cm for any system.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_debe8b6670b97b', 'les_604d79ad83a8b6', 'learn', 1, 'definition', '{"term":"Continuous objects","body":"Replace the sum $\\sum m_ix_i$ with an integral: $x_{cm} = \\frac{1}{M}\\int x\\,dm$. For a rod with linear density $\\lambda(x)$, $dm = \\lambda\\,dx$ and $M = \\int\\lambda\\,dx$. For a uniform object, the center of mass is at the geometric center."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9df55d698c7f88', 'les_604d79ad83a8b6', 'learn', 2, 'worked_example', '{"title":"A 2 m rod with density λ = 3x kg/m","steps":[{"latex":"M = \\int_0^2 3x\\,dx = 6\\ \\text{kg}","explanation":""},{"latex":"x_{cm} = \\tfrac16\\int_0^2 3x^2\\,dx = \\tfrac{8}{6} \\approx 1.33\\ \\text{m}","explanation":"Shifted toward the denser end."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e07f9474cfea4e', 'les_604d79ad83a8b6', 'learn', 3, 'definition', '{"term":"Systems","body":"Summing Newton''s second law over every particle, internal forces cancel in pairs, leaving $\\sum\\vec F_{ext} = M\\vec a_{cm}$. The center of mass moves like a single particle carrying all the mass."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c134414938fe8b', 'les_604d79ad83a8b6', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Aircraft are loaded to keep the center of mass in a safe range, and a diver''s center of mass follows a parabola however they twist."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_debe8b6670b97b', 'les_604d79ad83a8b6', 1, 'practice', 'numeric', 2, 'A 2 m rod has λ = 2 + x kg/m. Find its mass.', '{"answer":6,"unit":"kg"}', '[]', '$2x + \frac{x^2}{2}$ from 0 to 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9df55d698c7f88', 'les_604d79ad83a8b6', 2, 'practice', 'numeric', 3, 'Find that rod''s center of mass, to two decimal places.', '{"answer":1.11,"tolerance":0.01,"unit":"m"}', '[]', '$\frac16\int_0^2 (2x + x^2)\,dx = \frac{1}{6}\left(4 + \frac83\right)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e07f9474cfea4e', 'les_604d79ad83a8b6', 3, 'practice', 'numeric', 2, 'A 1 m rod has λ = 6x² kg/m. Find x_cm, to two decimal places.', '{"answer":0.75,"tolerance":0.01,"unit":"m"}', '[]', '$M = 2$; $\int 6x^3\,dx = 1.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c134414938fe8b', 'les_604d79ad83a8b6', 4, 'review', 'multiple_choice', 3, 'If a rod''s density increases toward one end, its center of mass is…', '{"choices":["at the middle","closer to the denser end","closer to the lighter end","outside the rod"],"answer":1}', '[]', 'More mass, more weight in the average.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_604d79ad83a8b6', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_604d79ad83a8b6', (SELECT id FROM formulas WHERE slug = 'calculus-rotation'), 1);

-- Lesson: calc-circular-motion
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b4c81114fac6ec', 'calc-circular-motion', 'Circular motion', 'Analyze circular motion with changing speed, banked curves and vertical loops, combining tangential and centripetal acceleration.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4e42fa6c20d6fc', 'les_b4c81114fac6ec', 1, 'Combine tangential acceleration dv/dt with centripetal acceleration v²/r.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c6dc0d5cdba115', 'les_b4c81114fac6ec', 2, 'Find the ideal banking angle, tan θ = v²/(rg).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_75c35513afde5f', 'les_b4c81114fac6ec', 3, 'Find the minimum speed at the top of a vertical loop, v = √(gr).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4e42fa6c20d6fc', 'les_b4c81114fac6ec', 'learn', 1, 'definition', '{"term":"Two accelerations","body":"On a curved path, acceleration has a tangential part $a_t = \\frac{dv}{dt}$ (changing speed) and a radial part $a_c = \\frac{v^2}{r}$ (changing direction). The net force''s radial component must supply $\\frac{mv^2}{r}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c6dc0d5cdba115', 'les_b4c81114fac6ec', 'learn', 2, 'worked_example', '{"title":"A car on a 4 m radius track with speed v = 2t","steps":[{"latex":"a_t = \\tfrac{dv}{dt} = 2\\ \\text{m/s}^2","explanation":""},{"latex":"t = 2:\\ a_c = \\tfrac{4^2}{4} = 4\\ \\text{m/s}^2","explanation":""},{"latex":"a = \\sqrt{2^2 + 4^2} \\approx 4.47\\ \\text{m/s}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_75c35513afde5f', 'les_b4c81114fac6ec', 'learn', 3, 'definition', '{"term":"Banked curves","body":"On a frictionless bank at angle $\\theta$, the normal force''s horizontal component provides the centripetal force: $N\\sin\\theta = \\frac{mv^2}{r}$ and $N\\cos\\theta = mg$, so $\\tan\\theta = \\frac{v^2}{rg}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ac2dc526dcaca8', 'les_b4c81114fac6ec', 'learn', 4, 'worked_example', '{"title":"Design a 100 m radius curve for 20 m/s","steps":[{"latex":"\\theta = \\tan^{-1}\\tfrac{20^2}{100(9.8)} \\approx 22.2°","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f5b3e4dec19f5a', 'les_b4c81114fac6ec', 'learn', 5, 'definition', '{"term":"Vertical loops","body":"At the top of a loop, gravity and the normal force both point toward the center: $N + mg = \\frac{mv^2}{r}$. The track just stops pushing ($N = 0$) at $v = \\sqrt{gr}$; any slower and the cart leaves the track."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_712c0f8bf37375', 'les_b4c81114fac6ec', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Highway ramps are banked, and roller-coaster loops are teardrop-shaped (clothoids) so riders don''t feel huge forces at the bottom."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4e42fa6c20d6fc', 'les_b4c81114fac6ec', 1, 'practice', 'numeric', 2, 'Find the minimum speed at the top of a 5 m radius loop.', '{"answer":7,"unit":"m/s"}', '[]', '$\sqrt{9.8 \times 5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c6dc0d5cdba115', 'les_b4c81114fac6ec', 2, 'practice', 'numeric', 3, 'A 60 kg rider moves at 10 m/s at the bottom of a 5 m radius loop. Find the normal force on them.', '{"answer":1788,"unit":"N"}', '[]', '$N - mg = \frac{mv^2}{r}$, so $N = 588 + 1200$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_75c35513afde5f', 'les_b4c81114fac6ec', 3, 'practice', 'multiple_choice', 2, 'A car slows down while rounding a curve. Its acceleration points…', '{"choices":["straight to the center","backward along the path","inward and backward","outward"],"answer":2}', '[]', 'Centripetal plus negative tangential.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ac2dc526dcaca8', 'les_b4c81114fac6ec', 4, 'review', 'multiple_choice', 3, 'On a banked curve, faster than the design speed, friction on the tires points…', '{"choices":["up the bank","down the bank","nowhere","forward"],"answer":1}', '[]', 'More centripetal force is needed, so friction adds an inward component.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b4c81114fac6ec', (SELECT id FROM concepts WHERE slug = 'circular-motion'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b4c81114fac6ec', (SELECT id FROM formulas WHERE slug = 'centripetal-acceleration'), 1);

-- Lesson: calc-collisions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9a6312af84c04e', 'calc-collisions', 'Elastic and inelastic collisions', 'Solve 1D elastic collisions with the relative-velocity rule, analyze 2D collisions with components, and use the center-of-mass frame.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b0caefe9478fa6', 'les_9a6312af84c04e', 1, 'Use the elastic-collision rule: relative velocity reverses, v₁ − v₂ = −(v₁′ − v₂′).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6f5d80e16fd6ce', 'les_9a6312af84c04e', 2, 'Solve 2D collisions by conserving momentum in x and y separately.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_354f4ec4b1c684', 'les_9a6312af84c04e', 3, 'Show that equal masses in a 2D elastic collision (one at rest) leave at 90°.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0caefe9478fa6', 'les_9a6312af84c04e', 'learn', 1, 'definition', '{"term":"Elastic shortcut","body":"Combining momentum and kinetic-energy conservation in 1D gives a linear condition: the relative velocity reverses, $v_1 - v_2 = -(v_1'' - v_2'')$. Use it with the momentum equation instead of the squared energy equation."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6f5d80e16fd6ce', 'les_9a6312af84c04e', 'learn', 2, 'definition', '{"term":"Two dimensions","body":"Momentum is a vector, so conserve each component: $\\sum p_x$ and $\\sum p_y$ separately. For an elastic collision, kinetic energy is also conserved."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_354f4ec4b1c684', 'les_9a6312af84c04e', 'learn', 3, 'worked_example', '{"title":"A 1 kg puck at 4 m/s hits an identical puck at rest elastically; the first leaves at 30° from its original direction","steps":[{"latex":"v_1'' = 4\\cos 30° \\approx 3.46\\ \\text{m/s}","explanation":""},{"latex":"v_2'' = 4\\sin 30° = 2\\ \\text{m/s}","explanation":"At 60° on the other side: the angle between them is 90°."}],"check":"Check: $3.46^2 + 2^2 = 16 = 4^2$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cdee29f312b05b', 'les_9a6312af84c04e', 'learn', 4, 'callout', '{"tone":"note","title":"Why 90°","body":"For equal masses, $\\vec v_1 = \\vec v_1'' + \\vec v_2''$ and $v_1^2 = v_1''^2 + v_2''^2$. By the Pythagorean theorem, the two outgoing velocities must be perpendicular."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_73e9bb65e77f87', 'les_9a6312af84c04e', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Billiards players use the 90° rule; particle physicists reconstruct invisible particles from momentum missing in collision products."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b0caefe9478fa6', 'les_9a6312af84c04e', 1, 'practice', 'numeric', 3, 'A 2 kg cart at 5 m/s hits a 3 kg cart at rest elastically. Find the 3 kg cart''s final velocity.', '{"answer":4,"unit":"m/s"}', '[]', '$v_2'' = \frac{2m_1}{m_1 + m_2}v_1 = \frac{4}{5}(5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6f5d80e16fd6ce', 'les_9a6312af84c04e', 2, 'practice', 'numeric', 2, 'Find the 2 kg cart''s final velocity in that collision.', '{"answer":-1,"unit":"m/s"}', '[]', '$\frac{m_1 - m_2}{m_1 + m_2}v_1 = -\frac15(5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_354f4ec4b1c684', 'les_9a6312af84c04e', 3, 'practice', 'numeric', 3, 'A 1 kg ball at 3 m/s east collides with a 1 kg ball at 4 m/s north; they stick. Find their speed.', '{"answer":2.5,"unit":"m/s"}', '[]', '$\frac{\sqrt{3^2 + 4^2}}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cdee29f312b05b', 'les_9a6312af84c04e', 4, 'review', 'multiple_choice', 3, 'In an elastic head-on collision, the speed of approach equals…', '{"choices":["zero","the speed of separation","twice the speed of separation","the final speed of the heavier object"],"answer":1}', '[]', 'Relative velocity reverses.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9a6312af84c04e', (SELECT id FROM concepts WHERE slug = 'momentum'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9a6312af84c04e', (SELECT id FROM formulas WHERE slug = 'momentum-impulse'), 1);

-- Lesson: calc-connecting-linear-rotational
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_67b381c9241e29', 'calc-connecting-linear-rotational', 'Connecting linear and rotational motion', 'Differentiate s = rθ to link linear and angular quantities, and combine tangential and centripetal acceleration for points on spinning objects.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_403847c46a080a', 'les_67b381c9241e29', 1, 'Derive v = rω and a_t = rα by differentiating s = rθ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_457bd81771fa15', 'les_67b381c9241e29', 2, 'Find total acceleration from a_t and a_c = rω².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_31cf4660a1ac16', 'les_67b381c9241e29', 3, 'Apply the no-slip condition to strings, spools and gears.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_403847c46a080a', 'les_67b381c9241e29', 'learn', 1, 'definition', '{"term":"Differentiating arc length","body":"For a point at fixed radius $r$, $s = r\\theta$. Differentiating: $v = \\frac{ds}{dt} = r\\omega$ and $a_t = \\frac{dv}{dt} = r\\alpha$. The point also has $a_c = \\frac{v^2}{r} = r\\omega^2$ toward the axis."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_457bd81771fa15', 'les_67b381c9241e29', 'learn', 2, 'worked_example', '{"title":"A string unwinds from a spool (R = 0.05 m) with θ(t) = 4t² rad","steps":[{"latex":"s = R\\theta = 0.2t^2,\\ v = 0.4t","explanation":""},{"latex":"t = 2:\\ v = 0.8\\ \\text{m/s},\\ a_t = 0.4\\ \\text{m/s}^2","explanation":""},{"latex":"a_c = \\tfrac{0.8^2}{0.05} = 12.8\\ \\text{m/s}^2","explanation":"For a point on the rim. The string itself has only a_t."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_31cf4660a1ac16', 'les_67b381c9241e29', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Fishing reels, film reels and tape drives must adjust ω as the radius of wound material changes to keep v steady."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_403847c46a080a', 'les_67b381c9241e29', 1, 'practice', 'numeric', 2, 'A wheel of radius 0.3 m has ω(t) = 2t rad/s. Find the tangential acceleration of its rim.', '{"answer":0.6,"unit":"m/s²"}', '[]', '$r\alpha = 0.3(2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_457bd81771fa15', 'les_67b381c9241e29', 2, 'practice', 'numeric', 3, 'For that wheel at t = 1 s, find the magnitude of a rim point''s total acceleration, to two decimal places.', '{"answer":1.34,"tolerance":0.01,"unit":"m/s²"}', '[]', '$a_c = 0.3(4) = 1.2$; $\sqrt{0.6^2 + 1.2^2} \approx 1.34$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_31cf4660a1ac16', 'les_67b381c9241e29', 3, 'practice', 'multiple_choice', 2, 'A string wound on a spool doesn''t slip. Its linear acceleration equals…', '{"choices":["α","Rα","Rω²","α/R"],"answer":1}', '[]', '$a = R\alpha$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_67ccdcda4d8ce0', 'les_67b381c9241e29', 4, 'review', 'multiple_choice', 3, 'For a wheel spinning at constant ω, a rim point''s acceleration is…', '{"choices":["zero","tangential only","centripetal only","both"],"answer":2}', '[]', '$\alpha = 0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_67b381c9241e29', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_67b381c9241e29', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: calc-conservation-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_cab40569571a06', 'calc-conservation-energy', 'Conservation of energy', 'Apply energy conservation with conservative and nonconservative forces, and use potential-energy graphs to find turning points and allowed regions.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_468f57c6b9e221', 'les_cab40569571a06', 1, 'Use K_i + U_i + W_nc = K_f + U_f.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_856a7a12531f23', 'les_cab40569571a06', 2, 'Find turning points where E = U(x), and allowed regions where E ≥ U(x).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_266cc7e9c2f97e', 'les_cab40569571a06', 3, 'Account for friction as nonconservative work.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_468f57c6b9e221', 'les_cab40569571a06', 'learn', 1, 'definition', '{"term":"The energy equation","body":"$K_i + U_i + W_{nc} = K_f + U_f$, where $W_{nc}$ is the work of nonconservative forces like friction (usually negative). With $W_{nc} = 0$, mechanical energy $E = K + U$ is constant."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_856a7a12531f23', 'les_cab40569571a06', 'learn', 2, 'definition', '{"term":"Energy diagrams","body":"Since $K = E - U(x) \\ge 0$, a particle can only be where $U(x) \\le E$. It turns around at points where $U = E$; between them it oscillates."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_266cc7e9c2f97e', 'les_cab40569571a06', 'learn', 3, 'worked_example', '{"title":"A particle with E = 8 J moves in U(x) = 2x² J","steps":[{"latex":"2x^2 = 8 \\Rightarrow x = \\pm2\\ \\text{m}","explanation":"Turning points."},{"latex":"\\text{at}\\ x = 0:\\ K = 8\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af8df4cb26c351', 'les_cab40569571a06', 'learn', 4, 'worked_example', '{"title":"A 2 kg sled slides down a 5 m drop from rest; friction does −30 J","steps":[{"latex":"2(9.8)(5) - 30 = \\tfrac12(2)v^2","explanation":""},{"latex":"v = \\sqrt{68} \\approx 8.25\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1d8f7c2b1c2e6e', 'les_cab40569571a06', 'experiment', 5, 'activity', '{"activity":"work-integral","title":"Work by a force that changes sign","params":{"law":"decreasing","k":4,"x1":0,"x2":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9d3a6d14c9af05', 'les_cab40569571a06', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Roller-coaster design, pendulum clocks and orbital mechanics all track energy rather than forces, because it''s far simpler."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_468f57c6b9e221', 'les_cab40569571a06', 1, 'practice', 'numeric', 2, 'U(x) = 3x² J and E = 12 J. Find the positive turning point.', '{"answer":2,"unit":"m"}', '[]', '$3x^2 = 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_856a7a12531f23', 'les_cab40569571a06', 2, 'practice', 'numeric', 2, 'A 1 kg ball dropped from 10 m lands at 12 m/s. How much energy did air resistance remove?', '{"answer":26,"unit":"J"}', '[]', '$98 - 72$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_266cc7e9c2f97e', 'les_cab40569571a06', 3, 'practice', 'multiple_choice', 2, 'On an energy diagram, the kinetic energy at a point is…', '{"choices":["U(x)","E − U(x)","E + U(x)","the slope"],"answer":1}', '[]', '$K = E - U$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af8df4cb26c351', 'les_cab40569571a06', 4, 'review', 'multiple_choice', 3, 'If E is less than U(x) at every point, the particle…', '{"choices":["moves fastest there","can''t be in that region","oscillates there","stops there"],"answer":1}', '[]', 'K would be negative.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cab40569571a06', (SELECT id FROM concepts WHERE slug = 'energy'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_cab40569571a06', (SELECT id FROM formulas WHERE slug = 'work-energy'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_cab40569571a06', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 2);

-- Lesson: calc-first-third-laws
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9de0f98e3389e5', 'calc-first-third-laws', 'Newton''s first and third laws', 'Apply the first law to define inertial frames and the third law to interacting objects, including the varying tension along a massive rope.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e85a07e49e2c61', 'les_9de0f98e3389e5', 1, 'Use the first law to identify inertial reference frames.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f90ac2f9936078', 'les_9de0f98e3389e5', 2, 'Identify third-law pairs: equal size, opposite direction, acting on different objects.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_338acaa0299aa9', 'les_9de0f98e3389e5', 3, 'Find tension as a function of position in an accelerating massive rope.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e85a07e49e2c61', 'les_9de0f98e3389e5', 'learn', 1, 'definition', '{"term":"First law and inertial frames","body":"With zero net force, velocity is constant. Frames where this holds are inertial; an accelerating car or a spinning merry-go-round is not one, which is why loose objects seem to slide on their own there."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f90ac2f9936078', 'les_9de0f98e3389e5', 'learn', 2, 'definition', '{"term":"Third law","body":"If A pushes on B, then B pushes on A with an equal and opposite force: $\\vec F_{AB} = -\\vec F_{BA}$. The pair acts on different objects, so the two forces never cancel each other in one free-body diagram."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_338acaa0299aa9', 'les_9de0f98e3389e5', 'learn', 3, 'definition', '{"term":"Massive ropes","body":"A massless rope has the same tension throughout. A rope with mass needs a net force on each piece to accelerate it, so its tension changes along its length."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1806905f9cdc7b', 'les_9de0f98e3389e5', 'learn', 4, 'worked_example', '{"title":"A 20 N pull drags a 1 kg rope attached to a 3 kg block across a frictionless floor","steps":[{"latex":"a = \\tfrac{20}{3 + 1} = 5\\ \\text{m/s}^2","explanation":""},{"latex":"T_{block\\ end} = 3(5) = 15\\ \\text{N}","explanation":"Only the block is ahead of this point."},{"latex":"T_{middle} = (3 + 0.5)(5) = 17.5\\ \\text{N}","explanation":"The block plus half the rope."}],"check":"In general $T(x) = (m_{block} + \\lambda x)a$ rises linearly from 15 N to 20 N along the rope."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97f8fd5fc98929', 'les_9de0f98e3389e5', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Tug-of-war is won with friction on the ground, not rope tension; heavy towing cables and elevator cables are designed for the highest tension, at the top."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e85a07e49e2c61', 'les_9de0f98e3389e5', 1, 'practice', 'numeric', 2, 'A uniform 2 kg rope is pulled by 10 N alone on a frictionless floor. Find the tension at its midpoint.', '{"answer":5,"unit":"N"}', '[]', '$a = 5$ m/s²; the trailing half (1 kg) needs 5 N.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f90ac2f9936078', 'les_9de0f98e3389e5', 2, 'practice', 'multiple_choice', 2, 'A book rests on a table. The third-law partner of the book''s weight is…', '{"choices":["the table''s normal force on the book","the book''s gravitational pull on Earth","the table''s weight","friction"],"answer":1}', '[]', 'Weight is Earth pulling the book, so its partner is the book pulling Earth.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_338acaa0299aa9', 'les_9de0f98e3389e5', 3, 'practice', 'multiple_choice', 2, 'Which frame is NOT inertial?', '{"choices":["a train moving at constant velocity","a car turning a corner","a frame drifting in deep space","a lab, to good approximation"],"answer":1}', '[]', 'It''s accelerating.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1806905f9cdc7b', 'les_9de0f98e3389e5', 4, 'review', 'multiple_choice', 3, 'A truck hits a mosquito. The force on the mosquito is…', '{"choices":["larger","smaller","equal in size","zero"],"answer":2}', '[]', 'Third law: the same force, very different accelerations.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9de0f98e3389e5', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));

-- Lesson: calc-friction
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_bc891a66f37fe0', 'calc-friction', 'Kinetic and static friction', 'Model static and kinetic friction, find when objects start to slide, and use calculus when the friction coefficient varies along the path.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a9c8d8531eb5c2', 'les_bc891a66f37fe0', 1, 'Use f_s ≤ μ_sN and f_k = μ_kN.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f391b6e7b55e67', 'les_bc891a66f37fe0', 2, 'Find the angle at which a block starts to slide, tan θ = μ_s.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c39ee57d0b5807', 'les_bc891a66f37fe0', 3, 'Solve motion with a position-dependent μ using a = v dv/dx.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a9c8d8531eb5c2', 'les_bc891a66f37fe0', 'learn', 1, 'definition', '{"term":"Friction models","body":"Static friction adjusts to whatever is needed to prevent sliding, up to $\\mu_sN$. Once sliding, kinetic friction is roughly constant: $f_k = \\mu_kN$, usually with $\\mu_k < \\mu_s$. On an incline, a block starts to slide when $\\tan\\theta = \\mu_s$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f391b6e7b55e67', 'les_bc891a66f37fe0', 'learn', 2, 'definition', '{"term":"Variable friction","body":"If $\\mu$ changes with position, use $a = v\\frac{dv}{dx}$: $v\\,dv = -\\mu(x)g\\,dx$, then integrate."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c39ee57d0b5807', 'les_bc891a66f37fe0', 'learn', 3, 'worked_example', '{"title":"A block slides at 4 m/s onto a rough patch where μ = 0.2x (x in meters)","steps":[{"latex":"v\\,dv = -0.2(9.8)x\\,dx","explanation":""},{"latex":"\\tfrac12(v^2 - 16) = -0.98x^2","explanation":""},{"latex":"v = 0 \\Rightarrow x = \\tfrac{4}{\\sqrt{1.96}} \\approx 2.86\\ \\text{m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0878e35ab0ad2b', 'les_bc891a66f37fe0', 'experiment', 4, 'activity', '{"activity":"forces-incline","title":"When does the block slip?","params":{"mass":5,"angle":30,"mus":0.4,"muk":0.3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e0a3d39a3e82cd', 'les_bc891a66f37fe0', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Anti-lock brakes keep tires near the static-friction limit for the shortest stops, and road crews grade surfaces so friction rises toward sharp curves."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a9c8d8531eb5c2', 'les_bc891a66f37fe0', 1, 'practice', 'numeric', 2, 'A block on a ramp starts to slide at 25°. Find μ_s, to two decimal places.', '{"answer":0.47,"tolerance":0.01}', '[]', '$\tan 25° \approx 0.466$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f391b6e7b55e67', 'les_bc891a66f37fe0', 2, 'practice', 'numeric', 3, 'A block slides at 6 m/s onto a surface with μ = 0.1x. How far does it go? Give two decimal places.', '{"answer":6.06,"tolerance":0.02,"unit":"m"}', '[]', '$18 = 0.49x^2$, so $x = \sqrt{36.7} \approx 6.06$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c39ee57d0b5807', 'les_bc891a66f37fe0', 3, 'practice', 'multiple_choice', 2, 'A 10 kg crate sits on a floor (μ_s = 0.5). You push horizontally with 30 N. The friction force is…', '{"choices":["49 N","30 N","0 N","19 N"],"answer":1}', '[]', 'Static friction matches the push, up to 49 N.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0878e35ab0ad2b', 'les_bc891a66f37fe0', 4, 'review', 'multiple_choice', 3, 'Kinetic friction on a sliding block depends mainly on…', '{"choices":["speed","contact area","normal force","time"],"answer":2}', '[]', '$f_k = \mu_kN$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bc891a66f37fe0', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));

-- Lesson: calc-gravitational-force
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9b03c6b41cfb79', 'calc-gravitational-force', 'Gravitational force', 'Use Newton''s law of gravitation and the gravitational field g(r), apply the shell theorem, and find the field inside a uniform planet.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_af54fa1186eefe', 'les_9b03c6b41cfb79', 1, 'Compute gravitational forces and fields, g = GM/r².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_73cb97398559dd', 'les_9b03c6b41cfb79', 2, 'State the shell theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2e473c5b3eea87', 'les_9b03c6b41cfb79', 3, 'Show that inside a uniform sphere g = GMr/R³, increasing linearly from the center.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af54fa1186eefe', 'les_9b03c6b41cfb79', 'learn', 1, 'definition', '{"term":"Field","body":"The gravitational field is force per unit mass: $\\vec g = \\frac{\\vec F}{m}$, of size $\\frac{GM}{r^2}$ outside a spherical mass $M$. With $G = 6.674\\times10^{-11}$ N·m²/kg², Earth''s surface field is about 9.8 N/kg."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_73cb97398559dd', 'les_9b03c6b41cfb79', 'learn', 2, 'definition', '{"term":"Shell theorem","body":"Newton proved, by integrating over the mass, that a uniform spherical shell attracts an outside mass as if all its mass were at its center, and exerts zero net force on a mass inside it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2e473c5b3eea87', 'les_9b03c6b41cfb79', 'learn', 3, 'definition', '{"term":"Inside a uniform planet","body":"At radius $r < R$, only the mass inside $r$ pulls: $M_{in} = M\\frac{r^3}{R^3}$, so $g = \\frac{GM_{in}}{r^2} = \\frac{GMr}{R^3}$. The field grows linearly from zero at the center to its maximum at the surface, then falls off as $\\frac{1}{r^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_43538e0d08282f', 'les_9b03c6b41cfb79', 'learn', 4, 'worked_example', '{"title":"Earth''s field at its surface, halfway to the center and at 2R (uniform-density model)","steps":[{"latex":"g(R) = \\tfrac{GM}{R^2} \\approx 9.82\\ \\text{N/kg}","explanation":""},{"latex":"g\\left(\\tfrac R2\\right) = \\tfrac{g(R)}{2} \\approx 4.91\\ \\text{N/kg}","explanation":"Linear inside."},{"latex":"g(2R) = \\tfrac{g(R)}{4} \\approx 2.45\\ \\text{N/kg}","explanation":"Inverse square outside."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a900a88f559283', 'les_9b03c6b41cfb79', 'learn', 5, 'callout', '{"tone":"note","title":"Real Earth","body":"Earth''s density isn''t uniform (its iron core is dense), so g actually rises slightly below the surface before falling; the uniform model is the AP approximation."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_37bf8ebf8a9c5b', 'les_9b03c6b41cfb79', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Gravimeters map oil and mineral deposits from tiny changes in g, and GRACE satellites track melting ice sheets the same way."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af54fa1186eefe', 'les_9b03c6b41cfb79', 1, 'practice', 'numeric', 2, 'At what height above Earth''s surface (as a multiple of R) is g a quarter of its surface value?', '{"answer":1}', '[]', 'At $r = 2R$, a height of 1R.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_73cb97398559dd', 'les_9b03c6b41cfb79', 2, 'practice', 'numeric', 2, 'In the uniform model, find g at r = 0.25R in N/kg, to two decimal places.', '{"answer":2.45,"tolerance":0.01,"unit":"N/kg"}', '[]', '$0.25 \times 9.82$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2e473c5b3eea87', 'les_9b03c6b41cfb79', 3, 'practice', 'multiple_choice', 2, 'A mass sits inside a hollow uniform spherical shell, off-center. The shell''s net gravitational force on it is…', '{"choices":["toward the center","toward the nearest wall","zero","infinite"],"answer":2}', '[]', 'Shell theorem.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_43538e0d08282f', 'les_9b03c6b41cfb79', 4, 'review', 'multiple_choice', 3, 'Where is g largest for a uniform-density planet?', '{"choices":["at the center","at the surface","at infinity","halfway down"],"answer":1}', '[]', 'It rises linearly inside, then falls outside.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9b03c6b41cfb79', (SELECT id FROM concepts WHERE slug = 'circular-motion'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9b03c6b41cfb79', (SELECT id FROM formulas WHERE slug = 'universal-gravitation'), 1);

-- Lesson: calc-impulse
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0e4931615f1c6c', 'calc-impulse', 'Change in momentum and impulse', 'Compute impulse as the time integral of force, find peak and average forces in collisions, and read impulse from force–time graphs.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8b908e589d02ed', 'les_0e4931615f1c6c', 1, 'Compute J = ∫F dt and use J = Δp.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_853dc233752552', 'les_0e4931615f1c6c', 2, 'Find average force F_avg = J/Δt and peak force from a force function.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4dd6607006d198', 'les_0e4931615f1c6c', 3, 'Read impulse as area under an F–t graph.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8b908e589d02ed', 'les_0e4931615f1c6c', 'learn', 1, 'definition', '{"term":"Impulse","body":"Integrating $F = \\frac{dp}{dt}$ over time gives the impulse–momentum theorem: $\\vec J = \\int_{t_1}^{t_2}\\vec F\\,dt = \\Delta\\vec p$. The average force over the contact is $F_{avg} = \\frac{J}{\\Delta t}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_853dc233752552', 'les_0e4931615f1c6c', 'learn', 2, 'worked_example', '{"title":"A bat''s force on a 0.1 kg ball is F(t) = 6 × 10⁶ t(0.01 − t) N for 0 ≤ t ≤ 0.01 s; the ball starts at rest","steps":[{"latex":"J = 6\\times10^6\\int_0^{0.01}(0.01t - t^2)\\,dt","explanation":""},{"latex":"J = 6\\times10^6\\left(\\tfrac{10^{-6}}{2} - \\tfrac{10^{-6}}{3}\\right) = 1.0\\ \\text{N·s}","explanation":""},{"latex":"v = \\tfrac{J}{m} = 10\\ \\text{m/s}","explanation":""},{"latex":"F_{peak} = F(0.005) = 150\\ \\text{N}","explanation":"The force peaks halfway through the contact."},{"latex":"F_{avg} = \\tfrac{1.0}{0.01} = 100\\ \\text{N}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4dd6607006d198', 'les_0e4931615f1c6c', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Airbags and crumple zones stretch the collision time so the same impulse comes with a smaller average force; force plates in sports labs integrate F(t) to measure jump impulses."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8b908e589d02ed', 'les_0e4931615f1c6c', 1, 'practice', 'numeric', 2, 'F(t) = 4t² N acts from t = 0 to 3 s. Find the impulse.', '{"answer":36,"unit":"N·s"}', '[]', '$\frac43t^3$ from 0 to 3.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_853dc233752552', 'les_0e4931615f1c6c', 2, 'practice', 'numeric', 2, 'A force–time graph is a triangle with peak 200 N lasting 0.05 s. Find the impulse.', '{"answer":5,"unit":"N·s"}', '[]', '$\frac12(0.05)(200)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4dd6607006d198', 'les_0e4931615f1c6c', 3, 'practice', 'numeric', 3, 'A 0.5 kg ball moving at 8 m/s receives F(t) = −120t N for 0 ≤ t ≤ 0.5 s. Find its final velocity.', '{"answer":-22,"unit":"m/s"}', '[]', '$J = -60(0.25) = -15$, so $v = 8 - 30$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1f6d4e518e49a8', 'les_0e4931615f1c6c', 4, 'review', 'multiple_choice', 3, 'Two collisions deliver the same impulse, one lasting twice as long. Its average force is…', '{"choices":["twice as large","half as large","the same","four times as large"],"answer":1}', '[]', '$F_{avg} = \frac{J}{\Delta t}$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0e4931615f1c6c', (SELECT id FROM concepts WHERE slug = 'momentum'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0e4931615f1c6c', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: calc-kinematics-derivatives
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c5fcc4b1cd87ed', 'calc-kinematics-derivatives', 'Displacement, velocity and acceleration as derivatives', 'Define instantaneous velocity and acceleration as derivatives of position, find when an object is at rest or turning around, and tell speeding up from slowing down.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c5e3212bd13994', 'les_c5fcc4b1cd87ed', 1, 'Compute v = dx/dt and a = dv/dt = d²x/dt² from a position function.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4d9ce8d2cb2686', 'les_c5fcc4b1cd87ed', 2, 'Find when an object is at rest and when it changes direction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f11a3cf1f0ec8f', 'les_c5fcc4b1cd87ed', 3, 'Decide whether an object is speeding up or slowing down from the signs of v and a.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c5e3212bd13994', 'les_c5fcc4b1cd87ed', 'learn', 1, 'definition', '{"term":"Instantaneous rates","body":"Average velocity over an interval, $\\frac{\\Delta x}{\\Delta t}$, becomes the instantaneous velocity in the limit $\\Delta t \\to 0$: $v = \\frac{dx}{dt}$, the slope of the position graph. Likewise $a = \\frac{dv}{dt} = \\frac{d^2x}{dt^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4d9ce8d2cb2686', 'les_c5fcc4b1cd87ed', 'learn', 2, 'worked_example', '{"title":"x(t) = t³ − 6t² + 9t (meters, seconds)","steps":[{"latex":"v = 3t^2 - 12t + 9 = 3(t - 1)(t - 3)","explanation":""},{"latex":"a = 6t - 12","explanation":""},{"latex":"v = 0\\ \\text{at}\\ t = 1\\ \\text{s and}\\ t = 3\\ \\text{s}","explanation":"Turning points: v changes sign at both."},{"latex":"t = 2:\\ x = 2\\ \\text{m},\\ v = -3\\ \\text{m/s},\\ a = 0","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f11a3cf1f0ec8f', 'les_c5fcc4b1cd87ed', 'learn', 3, 'definition', '{"term":"Speeding up or slowing down","body":"Speed increases when $v$ and $a$ have the same sign, and decreases when they have opposite signs. In the example, between 1 s and 2 s both are negative, so the object speeds up while moving backward; between 2 s and 3 s it slows down."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_03fab133afe6c2', 'les_c5fcc4b1cd87ed', 'experiment', 4, 'activity', '{"activity":"motion-graphs","title":"Position and velocity graphs together"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_25f9f874ad1e97', 'les_c5fcc4b1cd87ed', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Phone accelerometers and car crash sensors measure a; navigation software integrates and differentiates to track motion between GPS fixes."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c5e3212bd13994', 'les_c5fcc4b1cd87ed', 1, 'practice', 'numeric', 2, 'For x(t) = 4t² − t³, find v at t = 1 s.', '{"answer":5,"unit":"m/s"}', '[]', '$v = 8t - 3t^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4d9ce8d2cb2686', 'les_c5fcc4b1cd87ed', 2, 'practice', 'numeric', 2, 'For the same motion, find a at t = 1 s.', '{"answer":2,"unit":"m/s²"}', '[]', '$a = 8 - 6t$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f11a3cf1f0ec8f', 'les_c5fcc4b1cd87ed', 3, 'practice', 'numeric', 3, 'For x(t) = 4t² − t³, at what positive time is the object momentarily at rest? Give two decimal places.', '{"answer":2.67,"tolerance":0.01,"unit":"s"}', '[]', '$8t - 3t^2 = 0$ gives $t = \frac83$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_03fab133afe6c2', 'les_c5fcc4b1cd87ed', 4, 'review', 'multiple_choice', 3, 'At an instant, v = −2 m/s and a = +3 m/s². The object is…', '{"choices":["speeding up","slowing down","at rest","moving at constant speed"],"answer":1}', '[]', 'Opposite signs: slowing down.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c5fcc4b1cd87ed', (SELECT id FROM concepts WHERE slug = 'kinematics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_c5fcc4b1cd87ed', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: calc-kinematics-integrals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a4a2ab33288727', 'calc-kinematics-integrals', 'Representing motion with integrals and graphs', 'Recover velocity and position from acceleration by integrating with initial conditions, and distinguish displacement from distance traveled.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_237b076e0587ab', 'les_a4a2ab33288727', 1, 'Integrate a(t) to get v(t), and v(t) to get x(t), using initial conditions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8949efb8764df8', 'les_a4a2ab33288727', 2, 'Interpret area under v–t and a–t graphs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bfd6b52e0a4b13', 'les_a4a2ab33288727', 3, 'Compute displacement and total distance from a velocity function.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_237b076e0587ab', 'les_a4a2ab33288727', 'learn', 1, 'definition', '{"term":"Undoing derivatives","body":"$v(t) = v_0 + \\int_0^t a\\,dt''$ and $x(t) = x_0 + \\int_0^t v\\,dt''$. Geometrically, the area under a velocity graph is the displacement, and the area under an acceleration graph is the change in velocity. The constant-acceleration equations are the special case $a = \\text{const}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8949efb8764df8', 'les_a4a2ab33288727', 'learn', 2, 'worked_example', '{"title":"a(t) = 6t, with v₀ = 2 m/s and x₀ = 1 m","steps":[{"latex":"v = 2 + 3t^2","explanation":""},{"latex":"x = 1 + 2t + t^3","explanation":""},{"latex":"t = 2:\\ v = 14\\ \\text{m/s},\\ x = 13\\ \\text{m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bfd6b52e0a4b13', 'les_a4a2ab33288727', 'learn', 3, 'definition', '{"term":"Displacement vs distance","body":"Displacement is $\\int v\\,dt$; distance is $\\int |v|\\,dt$. Split the integral wherever $v$ changes sign."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7e5d2e60b1e5e4', 'les_a4a2ab33288727', 'learn', 4, 'worked_example', '{"title":"v(t) = t² − 4 from t = 0 to 3 s","steps":[{"latex":"\\Delta x = \\int_0^3 (t^2 - 4)\\,dt = 9 - 12 = -3\\ \\text{m}","explanation":""},{"latex":"d = \\int_0^2 (4 - t^2)\\,dt + \\int_2^3 (t^2 - 4)\\,dt","explanation":"v changes sign at t = 2."},{"latex":"d = \\tfrac{16}{3} + \\tfrac{7}{3} = \\tfrac{23}{3} \\approx 7.67\\ \\text{m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_162b1817d46d22', 'les_a4a2ab33288727', 'experiment', 5, 'activity', '{"activity":"accumulation","title":"Accumulating area under a curve"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_15aafa39c150cb', 'les_a4a2ab33288727', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Inertial navigation in aircraft and submarines integrates measured accelerations twice to track position when GPS isn''t available."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_237b076e0587ab', 'les_a4a2ab33288727', 1, 'practice', 'numeric', 2, 'a(t) = 4 − 2t from rest at the origin. Find v at t = 3 s.', '{"answer":3,"unit":"m/s"}', '[]', '$v = 4t - t^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8949efb8764df8', 'les_a4a2ab33288727', 2, 'practice', 'numeric', 2, 'For the same motion, find x at t = 3 s.', '{"answer":9,"unit":"m"}', '[]', '$x = 2t^2 - \frac{t^3}{3} = 18 - 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bfd6b52e0a4b13', 'les_a4a2ab33288727', 3, 'practice', 'numeric', 3, 'v(t) = 2t − 4 from 0 to 4 s. Find the total distance traveled.', '{"answer":8,"unit":"m"}', '[]', 'Each half (0–2 s and 2–4 s) covers 4 m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7e5d2e60b1e5e4', 'les_a4a2ab33288727', 4, 'review', 'multiple_choice', 3, 'The area under an a–t graph from t₁ to t₂ equals…', '{"choices":["displacement","change in velocity","average acceleration","jerk"],"answer":1}', '[]', '$\int a\,dt = \Delta v$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a4a2ab33288727', (SELECT id FROM concepts WHERE slug = 'kinematics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a4a2ab33288727', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: calc-linear-momentum
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f2be30a607af34', 'calc-linear-momentum', 'Linear momentum', 'Use F = dp/dt for changing momentum, including systems that gain mass, and connect system momentum to the center of mass velocity.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a47449ec9dbf77', 'les_f2be30a607af34', 1, 'Find force from a momentum function, F = dp/dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9b3f5d8abd408d', 'les_f2be30a607af34', 2, 'Handle mass flow: the force needed to bring added mass up to speed is v dm/dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f136835e92b57d', 'les_f2be30a607af34', 3, 'Use p_total = M v_cm = M dx_cm/dt.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a47449ec9dbf77', 'les_f2be30a607af34', 'learn', 1, 'definition', '{"term":"Momentum and force","body":"$\\vec p = m\\vec v$ and $\\vec F_{net} = \\frac{d\\vec p}{dt}$. If $p(t)$ is known, differentiate to get the force."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9b3f5d8abd408d', 'les_f2be30a607af34', 'learn', 2, 'worked_example', '{"title":"p(t) = 3t² kg·m/s","steps":[{"latex":"F = \\tfrac{dp}{dt} = 6t","explanation":""},{"latex":"F(2) = 12\\ \\text{N}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f136835e92b57d', 'les_f2be30a607af34', 'learn', 3, 'definition', '{"term":"Mass flow","body":"When mass is added to a system moving at constant $v$ (sand dropped on a conveyor belt), the momentum still grows: $\\frac{dp}{dt} = v\\frac{dm}{dt}$. That''s the force the motor must supply."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fbd3aea919403f', 'les_f2be30a607af34', 'learn', 4, 'worked_example', '{"title":"Sand falls straight down onto a belt moving at 2 m/s, at 5 kg/s","steps":[{"latex":"F = v\\tfrac{dm}{dt} = 2(5) = 10\\ \\text{N}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_562a066eb3a490', 'les_f2be30a607af34', 'learn', 5, 'definition', '{"term":"Systems","body":"$\\vec p_{tot} = \\sum m_i\\vec v_i = M\\vec v_{cm}$, since $\\vec v_{cm} = \\frac{d\\vec r_{cm}}{dt}$. If $\\sum \\vec F_{ext} = 0$, the center of mass keeps a constant velocity."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bacd15e6e6e5fb', 'les_f2be30a607af34', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Conveyor belts, rockets (which lose mass) and water jets hitting turbine blades are all mass-flow problems."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a47449ec9dbf77', 'les_f2be30a607af34', 1, 'practice', 'numeric', 2, 'p(t) = 4t − t² kg·m/s. Find the force at t = 1 s.', '{"answer":2,"unit":"N"}', '[]', '$4 - 2t$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9b3f5d8abd408d', 'les_f2be30a607af34', 2, 'practice', 'numeric', 2, 'Gravel drops at 8 kg/s onto a belt moving at 1.5 m/s. Find the extra force needed.', '{"answer":12,"unit":"N"}', '[]', '$1.5 \times 8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f136835e92b57d', 'les_f2be30a607af34', 3, 'practice', 'numeric', 2, 'A 2 kg mass at 3 m/s and a 4 kg mass at −1.5 m/s. Find v_cm.', '{"answer":0,"unit":"m/s"}', '[]', '$\frac{6 - 6}{6}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fbd3aea919403f', 'les_f2be30a607af34', 4, 'review', 'multiple_choice', 3, 'If a system''s total momentum is constant, the net external force is…', '{"choices":["constant","zero","increasing","equal to Mg"],"answer":1}', '[]', '$F = \frac{dp}{dt} = 0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f2be30a607af34', (SELECT id FROM concepts WHERE slug = 'momentum'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f2be30a607af34', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: calc-momentum-conservation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ea83f514583180', 'calc-momentum-conservation', 'Conservation of linear momentum', 'Derive momentum conservation from Newton''s third law, and solve explosions and the ballistic pendulum by combining momentum and energy.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bf2ca4a6ea6fef', 'les_ea83f514583180', 1, 'Derive conservation of momentum from the third law and F = dp/dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1d70d7cd1c07fa', 'les_ea83f514583180', 2, 'Solve explosions and recoil problems.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9e60c82e46abd9', 'les_ea83f514583180', 3, 'Solve the ballistic pendulum, using momentum for the collision and energy for the swing.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf2ca4a6ea6fef', 'les_ea83f514583180', 'learn', 1, 'definition', '{"term":"Why it''s conserved","body":"For two interacting objects, $\\frac{d\\vec p_1}{dt} = \\vec F_{21}$ and $\\frac{d\\vec p_2}{dt} = \\vec F_{12} = -\\vec F_{21}$. Adding gives $\\frac{d}{dt}(\\vec p_1 + \\vec p_2) = 0$. With no external force, total momentum is constant, whatever the internal forces do."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1d70d7cd1c07fa', 'les_ea83f514583180', 'learn', 2, 'worked_example', '{"title":"A 3 kg object at rest explodes into 1 kg at +6 m/s and a 2 kg piece","steps":[{"latex":"0 = 1(6) + 2v \\Rightarrow v = -3\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9e60c82e46abd9', 'les_ea83f514583180', 'learn', 3, 'worked_example', '{"title":"Ballistic pendulum: a 0.01 kg bullet embeds in a 2 kg block, which swings up 0.1 m","steps":[{"latex":"V = \\sqrt{2gh} = \\sqrt{2(9.8)(0.1)} = 1.4\\ \\text{m/s}","explanation":"Energy is conserved during the swing."},{"latex":"v_{bullet} = \\tfrac{(2.01)(1.4)}{0.01} \\approx 281\\ \\text{m/s}","explanation":"Momentum is conserved in the collision (energy is not)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_faddb8b4b0df7a', 'les_ea83f514583180', 'learn', 4, 'callout', '{"tone":"warning","title":"Order matters","body":"Don''t apply energy conservation to the embedding collision itself: most of the bullet''s kinetic energy becomes heat and deformation."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_15debf96c5d722', 'les_ea83f514583180', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Rocket staging, gun recoil and forensic ballistics; before electronic chronographs, ballistic pendulums were how bullet speeds were measured."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bf2ca4a6ea6fef', 'les_ea83f514583180', 1, 'practice', 'numeric', 2, 'A 60 kg skater at rest throws a 3 kg ball forward at 10 m/s. Find the skater''s recoil speed.', '{"answer":0.5,"unit":"m/s"}', '[]', '$\frac{30}{60}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1d70d7cd1c07fa', 'les_ea83f514583180', 2, 'practice', 'numeric', 3, 'A 0.02 kg bullet hits a 1.98 kg block, which rises 0.2 m. Find the bullet''s speed, to the nearest m/s.', '{"answer":198,"tolerance":1,"unit":"m/s"}', '[]', '$V = \sqrt{3.92} = 1.98$; $v = \frac{2(1.98)}{0.02}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9e60c82e46abd9', 'les_ea83f514583180', 3, 'practice', 'multiple_choice', 2, 'In a ballistic pendulum, which is conserved during the collision?', '{"choices":["kinetic energy","momentum","both","neither"],"answer":1}', '[]', 'It''s perfectly inelastic.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_faddb8b4b0df7a', 'les_ea83f514583180', 4, 'review', 'multiple_choice', 3, 'Total momentum is conserved when…', '{"choices":["no internal forces act","the net external force is zero","the collision is elastic","objects stick"],"answer":1}', '[]', 'Internal forces cancel in pairs.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ea83f514583180', (SELECT id FROM concepts WHERE slug = 'momentum'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ea83f514583180', (SELECT id FROM formulas WHERE slug = 'momentum-impulse'), 1);

-- Lesson: calc-motion-2d
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_fb7007ac2c68da', 'calc-motion-2d', 'Vectors and motion in two dimensions', 'Describe 2D motion with position vectors r(t), differentiate component by component, and analyze projectiles and uniform circular motion with calculus.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5e9751d49c5c4b', 'les_fb7007ac2c68da', 1, 'Write r(t) = x(t) î + y(t) ĵ and find v = dr/dt and a = dv/dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bfe0569fd17b58', 'les_fb7007ac2c68da', 2, 'Find speed, direction and the top of a projectile''s path.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6e71e363a60ec6', 'les_fb7007ac2c68da', 3, 'Show that uniform circular motion has acceleration of size rω² toward the center.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5e9751d49c5c4b', 'les_fb7007ac2c68da', 'learn', 1, 'definition', '{"term":"Vector kinematics","body":"$\\vec r(t) = x(t)\\,\\hat\\imath + y(t)\\,\\hat\\jmath$. Differentiate each component: $\\vec v = \\frac{d\\vec r}{dt}$ and $\\vec a = \\frac{d\\vec v}{dt}$. Speed is $|\\vec v| = \\sqrt{v_x^2 + v_y^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bfe0569fd17b58', 'les_fb7007ac2c68da', 'learn', 2, 'worked_example', '{"title":"A projectile with r(t) = 3t î + (4t − 4.9t²) ĵ","steps":[{"latex":"\\vec v = 3\\,\\hat\\imath + (4 - 9.8t)\\,\\hat\\jmath","explanation":""},{"latex":"\\vec a = -9.8\\,\\hat\\jmath","explanation":""},{"latex":"v_y = 0\\ \\text{at}\\ t = \\tfrac{4}{9.8} \\approx 0.41\\ \\text{s}","explanation":"The top of the path."},{"latex":"|\\vec v(1)| = \\sqrt{3^2 + 5.8^2} \\approx 6.53\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e71e363a60ec6', 'les_fb7007ac2c68da', 'learn', 3, 'worked_example', '{"title":"Uniform circular motion: r(t) = R cos(ωt) î + R sin(ωt) ĵ","steps":[{"latex":"\\vec v = -R\\omega\\sin(\\omega t)\\,\\hat\\imath + R\\omega\\cos(\\omega t)\\,\\hat\\jmath","explanation":""},{"latex":"\\vec a = -\\omega^2\\vec r","explanation":"Points to the center, with magnitude Rω²."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_17602618f5f47e', 'les_fb7007ac2c68da', 'experiment', 4, 'activity', '{"activity":"projectile","title":"Projectile components","params":{"speed":20,"angle":45}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d81d6488e256e9', 'les_fb7007ac2c68da', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Game engines and flight software update position vectors this way many times per second."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5e9751d49c5c4b', 'les_fb7007ac2c68da', 1, 'practice', 'numeric', 2, 'r(t) = t² î + 2t ĵ. Find the speed at t = 2 s, to two decimal places.', '{"answer":4.47,"tolerance":0.01,"unit":"m/s"}', '[]', '$\vec v = (2t, 2) = (4, 2)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bfe0569fd17b58', 'les_fb7007ac2c68da', 2, 'practice', 'numeric', 2, 'For r(t) = 5cos(2t) î + 5sin(2t) ĵ, find the magnitude of the acceleration.', '{"answer":20,"unit":"m/s²"}', '[]', '$R\omega^2 = 5(4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e71e363a60ec6', 'les_fb7007ac2c68da', 3, 'practice', 'multiple_choice', 2, 'For a projectile (no air resistance), which component of velocity stays constant?', '{"choices":["vertical","horizontal","both","neither"],"answer":1}', '[]', '$a_x = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_17602618f5f47e', 'les_fb7007ac2c68da', 4, 'review', 'multiple_choice', 3, 'In uniform circular motion, v and a are…', '{"choices":["parallel","perpendicular","opposite","both zero"],"answer":1}', '[]', '$\vec v \cdot \vec a = 0$ for constant speed.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_fb7007ac2c68da', (SELECT id FROM concepts WHERE slug = 'kinematics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_fb7007ac2c68da', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: calc-newtons-second-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_dd9c39c2aaae27', 'calc-newtons-second-law', 'Newton''s second law with variable forces', 'Write Newton''s second law as F = dp/dt, and solve for motion under forces that depend on time by integrating.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_102106c2c816da', 'les_dd9c39c2aaae27', 1, 'State Newton''s second law in momentum form, F_net = dp/dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_116c0634200118', 'les_dd9c39c2aaae27', 2, 'Find v(t) and x(t) when the net force varies with time.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bb7dbdbc78e2f1', 'les_dd9c39c2aaae27', 3, 'Set up the differential equation m dv/dt = F for a given force.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_102106c2c816da', 'les_dd9c39c2aaae27', 'learn', 1, 'definition', '{"term":"Momentum form","body":"$\\vec F_{net} = \\frac{d\\vec p}{dt}$. For constant mass this is $m\\vec a$. Writing it as a differential equation, $m\\frac{dv}{dt} = F$, lets us handle forces that change with time, position or velocity."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_116c0634200118', 'les_dd9c39c2aaae27', 'learn', 2, 'worked_example', '{"title":"F(t) = 6t newtons acts on a 2 kg mass starting from rest","steps":[{"latex":"a = \\tfrac{6t}{2} = 3t","explanation":""},{"latex":"v = \\int_0^t 3t''\\,dt'' = 1.5t^2","explanation":""},{"latex":"x = \\int_0^t 1.5t''^2\\,dt'' = 0.5t^3","explanation":""},{"latex":"t = 2:\\ v = 6\\ \\text{m/s},\\ x = 4\\ \\text{m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb7dbdbc78e2f1', 'les_dd9c39c2aaae27', 'learn', 3, 'definition', '{"term":"Forces that depend on position or velocity","body":"If $F = F(x)$, use $a = v\\frac{dv}{dx}$, so $\\int mv\\,dv = \\int F\\,dx$; this is the work–energy theorem. If $F = F(v)$, separate variables: $\\int \\frac{m\\,dv}{F(v)} = \\int dt$, as with air resistance."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_81da863a41564a', 'les_dd9c39c2aaae27', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Rocket engines whose thrust ramps up, cars whose engine force changes with speed, and robot arms with programmed force profiles are all modeled with F(t) or F(v)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_102106c2c816da', 'les_dd9c39c2aaae27', 1, 'practice', 'numeric', 2, 'F(t) = 12 − 3t (N) acts on a 3 kg mass starting from rest. Find v at t = 4 s.', '{"answer":8,"unit":"m/s"}', '[]', '$a = 4 - t$, so $v = 4t - \frac{t^2}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_116c0634200118', 'les_dd9c39c2aaae27', 2, 'practice', 'numeric', 3, 'A 0.5 kg object starts at 2 m/s with net force F = −t (N). When is it momentarily at rest? Give two decimal places.', '{"answer":1.41,"tolerance":0.01,"unit":"s"}', '[]', '$v = 2 - t^2$, so $t = \sqrt2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bb7dbdbc78e2f1', 'les_dd9c39c2aaae27', 3, 'practice', 'multiple_choice', 2, 'A constant net force acts on an object. Its momentum…', '{"choices":["stays constant","changes at a constant rate","grows exponentially","falls to zero"],"answer":1}', '[]', '$\frac{dp}{dt} = F$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_81da863a41564a', 'les_dd9c39c2aaae27', 4, 'review', 'multiple_choice', 3, 'To solve m dv/dt = −bv, the right first step is to…', '{"choices":["integrate both sides over x","separate variables: dv/v = −(b/m) dt","set v constant","differentiate again"],"answer":1}', '[]', 'Then integrate to get an exponential.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_dd9c39c2aaae27', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_dd9c39c2aaae27', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: calc-orbits-escape
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7558bf20d4a906', 'calc-orbits-escape', 'Motion of orbiting satellites', 'Derive gravitational potential energy by integrating Newton''s law, find escape speed and orbital energy, and apply conservation of energy and angular momentum to elliptical orbits.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d3bb7c911710b8', 'les_7558bf20d4a906', 1, 'Derive U = −GMm/r from W = ∫F dr.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b342661cb6c76c', 'les_7558bf20d4a906', 2, 'Compute escape speed √(2GM/R) and circular-orbit energy −GMm/(2r).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_045428f4b36854', 'les_7558bf20d4a906', 3, 'Use energy and angular momentum conservation between perigee and apogee.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d3bb7c911710b8', 'les_7558bf20d4a906', 'learn', 1, 'definition', '{"term":"Potential energy from the force","body":"Gravity''s work bringing $m$ from infinity to $r$: $W = \\int_\\infty^r \\left(-\\frac{GMm}{r''^2}\\right)dr'' = \\frac{GMm}{r}$, so $U(r) = -W = -\\frac{GMm}{r}$. Lifting from Earth''s surface to infinity takes $\\frac{GMm}{R}$: about $6.25\\times10^{10}$ J for a 1000 kg craft."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b342661cb6c76c', 'les_7558bf20d4a906', 'learn', 2, 'definition', '{"term":"Escape speed","body":"Just escaping means $K + U = 0$: $\\frac12mv^2 = \\frac{GMm}{R}$, so $v_{esc} = \\sqrt{\\frac{2GM}{R}} \\approx 11.2$ km/s from Earth''s surface, independent of the craft''s mass."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_045428f4b36854', 'les_7558bf20d4a906', 'learn', 3, 'definition', '{"term":"Elliptical orbits","body":"Between closest approach (perigee) and farthest (apogee), both $E = \\frac12mv^2 - \\frac{GMm}{r}$ and $L = mvr$ (perpendicular at these points) are conserved. Together they determine both speeds."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eb378c532f30a1', 'les_7558bf20d4a906', 'learn', 4, 'worked_example', '{"title":"A satellite at perigee r_p = 7 × 10⁶ m moves at 8.5 km/s. Find its speed at apogee r_a = 1.2 × 10⁷ m","steps":[{"latex":"v_a = \\tfrac{v_pr_p}{r_a} = \\tfrac{8500(7\\times10^6)}{1.2\\times10^7}","explanation":"Angular momentum conservation."},{"latex":"v_a \\approx 4960\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1fd7651b79f367', 'les_7558bf20d4a906', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Transfer orbits to geostationary altitude and to Mars are ellipses planned with exactly these two conservation laws."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d3bb7c911710b8', 'les_7558bf20d4a906', 1, 'practice', 'numeric', 2, 'Find the escape speed from the Moon (M = 7.35 × 10²² kg, R = 1.74 × 10⁶ m), in km/s, to two decimal places.', '{"answer":2.37,"tolerance":0.01,"unit":"km/s"}', '[]', '$\sqrt{\frac{2(6.674\times10^{-11})(7.35\times10^{22})}{1.74\times10^6}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b342661cb6c76c', 'les_7558bf20d4a906', 2, 'practice', 'numeric', 3, 'How much energy (in units of $10^{10}$ J) does it take to move a 1000 kg satellite from Earth''s surface into a circular orbit at r = 2R? Use GMm/R = 6.25 × 10¹⁰ J.', '{"answer":4.69,"tolerance":0.02}', '[]', '$E_f - E_i = -\frac{GMm}{4R} + \frac{GMm}{R} = \frac34(6.25)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_045428f4b36854', 'les_7558bf20d4a906', 3, 'practice', 'multiple_choice', 2, 'Escape speed from a planet depends on…', '{"choices":["the object''s mass","the planet''s mass and radius","the launch angle only","the object''s shape"],"answer":1}', '[]', '$\sqrt{\frac{2GM}{R}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eb378c532f30a1', 'les_7558bf20d4a906', 4, 'review', 'multiple_choice', 3, 'In an elliptical orbit, the satellite moves fastest at…', '{"choices":["apogee","perigee","the minor axis","constant speed"],"answer":1}', '[]', 'Smallest r, so the largest v for constant L.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7558bf20d4a906', (SELECT id FROM concepts WHERE slug = 'circular-motion'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7558bf20d4a906', (SELECT id FROM formulas WHERE slug = 'universal-gravitation'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7558bf20d4a906', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 2);

-- Lesson: calc-potential-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_461ac57869525b', 'calc-potential-energy', 'Potential energy and conservative forces', 'Define conservative forces, find potential energy from force by integration and force from potential energy by differentiation, and classify equilibrium points on U(x) graphs.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_66c76d973ff2ca', 'les_461ac57869525b', 1, 'Define a conservative force: path-independent work, zero work around closed loops.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_71098ba415dfe4', 'les_461ac57869525b', 2, 'Use ΔU = −∫F dx and F = −dU/dx.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b05ae7fb9a0efc', 'les_461ac57869525b', 3, 'Find equilibria where dU/dx = 0, and classify them with d²U/dx².');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_66c76d973ff2ca', 'les_461ac57869525b', 'learn', 1, 'definition', '{"term":"Conservative forces","body":"A force is conservative if its work between two points doesn''t depend on the path (gravity, springs, electric forces). Friction is not: a longer path does more negative work. Only conservative forces have a potential energy: $\\Delta U = -\\int_{x_1}^{x_2} F\\,dx$, and conversely $F = -\\frac{dU}{dx}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_71098ba415dfe4', 'les_461ac57869525b', 'learn', 2, 'worked_example', '{"title":"Spring and gravity potential energies from their forces","steps":[{"latex":"F = -kx \\Rightarrow U = \\tfrac12 kx^2","explanation":""},{"latex":"F = -\\tfrac{GMm}{r^2} \\Rightarrow U = -\\tfrac{GMm}{r}","explanation":"Choosing U = 0 at infinity."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b05ae7fb9a0efc', 'les_461ac57869525b', 'learn', 3, 'definition', '{"term":"Equilibrium","body":"Equilibrium is where $F = -\\frac{dU}{dx} = 0$, a flat spot on the $U(x)$ graph. A minimum ($U'''' > 0$) is stable: nudge it and it returns. A maximum ($U'''' < 0$) is unstable."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a464432e55cbe6', 'les_461ac57869525b', 'learn', 4, 'worked_example', '{"title":"U(x) = 2x³ − 6x (joules)","steps":[{"latex":"F = -\\tfrac{dU}{dx} = -6x^2 + 6","explanation":""},{"latex":"F = 0\\ \\text{at}\\ x = \\pm 1","explanation":""},{"latex":"U'''' = 12x:\\ x = 1\\ \\text{stable},\\ x = -1\\ \\text{unstable}","explanation":""},{"latex":"F(2) = -24 + 6 = -18\\ \\text{N}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f057a148a74e96', 'les_461ac57869525b', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Chemical bonds sit at the minimum of an interatomic potential, molecular models compute forces as $-\\nabla U$, and a ball balanced on a hill is an unstable equilibrium."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_66c76d973ff2ca', 'les_461ac57869525b', 1, 'practice', 'numeric', 2, 'U(x) = x⁴ − 2x². Find F at x = 0.5 m, to two decimal places.', '{"answer":1.5,"tolerance":0.01,"unit":"N"}', '[]', '$F = -4x^3 + 4x = -0.5 + 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_71098ba415dfe4', 'les_461ac57869525b', 2, 'practice', 'numeric', 3, 'For U(x) = x⁴ − 2x², how many stable equilibrium points are there?', '{"answer":2}', '[]', '$x = \pm1$ are minima ($U'''' = 8$); $x = 0$ is a maximum.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b05ae7fb9a0efc', 'les_461ac57869525b', 3, 'practice', 'multiple_choice', 2, 'Which force is NOT conservative?', '{"choices":["gravity","spring force","kinetic friction","electric force"],"answer":2}', '[]', 'Friction''s work depends on the path.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a464432e55cbe6', 'les_461ac57869525b', 4, 'review', 'multiple_choice', 3, 'At a point where U(x) has positive slope, the force points…', '{"choices":["+x","−x","nowhere","up"],"answer":1}', '[]', '$F = -\frac{dU}{dx}$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_461ac57869525b', (SELECT id FROM concepts WHERE slug = 'energy'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_461ac57869525b', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: calc-power
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_e5cf5b29faabf9', 'calc-power', 'Power', 'Define instantaneous power as the rate of work, P = dW/dt = F·v, and find energy transferred from a power function by integrating.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_916ef3d1299daf', 'les_e5cf5b29faabf9', 1, 'Compute instantaneous power P = dW/dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_53223656323d26', 'les_e5cf5b29faabf9', 2, 'Use P = F·v for forces on moving objects.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8ffe512bac0fe2', 'les_e5cf5b29faabf9', 3, 'Find work as the integral of power over time.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_916ef3d1299daf', 'les_e5cf5b29faabf9', 'learn', 1, 'definition', '{"term":"Instantaneous power","body":"$P = \\frac{dW}{dt}$. Since $dW = \\vec F\\cdot d\\vec r$, dividing by $dt$ gives $P = \\vec F\\cdot\\vec v$. Over an interval, $W = \\int P\\,dt$, the area under a power–time graph."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_53223656323d26', 'les_e5cf5b29faabf9', 'learn', 2, 'worked_example', '{"title":"A car''s engine delivers 60 kW at 30 m/s","steps":[{"latex":"F = \\tfrac{P}{v} = \\tfrac{60{,}000}{30} = 2000\\ \\text{N}","explanation":"At constant power, the driving force drops as speed rises."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8ffe512bac0fe2', 'les_e5cf5b29faabf9', 'learn', 3, 'worked_example', '{"title":"Work done is W(t) = 4t³ joules","steps":[{"latex":"P = \\tfrac{dW}{dt} = 12t^2","explanation":""},{"latex":"P(2) = 48\\ \\text{W}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6136936bfd5855', 'les_e5cf5b29faabf9', 'learn', 4, 'worked_example', '{"title":"Power P(t) = 6t watts from 0 to 3 s","steps":[{"latex":"W = \\int_0^3 6t\\,dt = 27\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b76daa432cd4ac', 'les_e5cf5b29faabf9', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Cyclists'' power meters measure force times pedal speed, and electric-vehicle range depends on drag power, which scales as $v^3$ for quadratic drag."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_916ef3d1299daf', 'les_e5cf5b29faabf9', 1, 'practice', 'numeric', 2, 'A 50 N force at 30° to the velocity acts on an object moving at 4 m/s. Find the power, to one decimal place.', '{"answer":173.2,"tolerance":0.1,"unit":"W"}', '[]', '$50 \cdot 4\cos 30°$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_53223656323d26', 'les_e5cf5b29faabf9', 2, 'practice', 'numeric', 2, 'P(t) = 3t² W. Find the energy delivered from t = 1 to 2 s.', '{"answer":7,"unit":"J"}', '[]', '$t^3$ from 1 to 2.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8ffe512bac0fe2', 'les_e5cf5b29faabf9', 3, 'practice', 'multiple_choice', 2, 'Quadratic drag force is cv². The power needed to overcome it scales as…', '{"choices":["v","v²","v³","constant"],"answer":2}', '[]', '$P = Fv = cv^3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6136936bfd5855', 'les_e5cf5b29faabf9', 4, 'review', 'multiple_choice', 3, 'A force perpendicular to the velocity delivers power…', '{"choices":["maximum","zero","negative","equal to Fv"],"answer":1}', '[]', '$\vec F\cdot\vec v = 0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_e5cf5b29faabf9', (SELECT id FROM concepts WHERE slug = 'energy'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_e5cf5b29faabf9', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: calc-rolling
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ad529bd15ce2c9', 'calc-rolling', 'Rolling', 'Analyze rolling with forces and torques to find acceleration and the static friction required, and solve the transition from sliding to rolling.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e158e04575b6d3', 'les_ad529bd15ce2c9', 1, 'Write Newton''s laws for translation and rotation of a rolling object and solve for a and f.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_43c2eec44ade46', 'les_ad529bd15ce2c9', 2, 'Find the minimum μ_s for rolling without slipping on an incline.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9be02612277ef0', 'les_ad529bd15ce2c9', 3, 'Solve a ball that starts sliding and ends rolling (v_final = 5/7 v₀ for a solid sphere).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e158e04575b6d3', 'les_ad529bd15ce2c9', 'learn', 1, 'definition', '{"term":"Forces on an incline","body":"Translation: $mg\\sin\\theta - f = ma$. Rotation about the center: $fR = I\\alpha = \\beta mR^2\\frac aR$. Solving: $a = \\frac{g\\sin\\theta}{1 + \\beta}$ and $f = \\frac{\\beta}{1 + \\beta}mg\\sin\\theta$. Rolling without slipping needs $f \\le \\mu_sN$, so $\\mu_s \\ge \\frac{\\beta}{1 + \\beta}\\tan\\theta$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_43c2eec44ade46', 'les_ad529bd15ce2c9', 'learn', 2, 'worked_example', '{"title":"A solid sphere (β = 2/5) on a 30° incline","steps":[{"latex":"a = \\tfrac{g\\sin 30°}{1.4} = 3.5\\ \\text{m/s}^2","explanation":""},{"latex":"\\mu_{s,min} = \\tfrac27\\tan 30° \\approx 0.165","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9be02612277ef0', 'les_ad529bd15ce2c9', 'learn', 3, 'definition', '{"term":"From sliding to rolling","body":"A bowling ball released sliding with $v_0$ and no spin: kinetic friction slows it while spinning it up until $v = R\\omega$. Angular momentum about the contact point on the floor is conserved (friction acts there): $mv_0R = mvR + I\\frac vR$, so $v = \\frac{v_0}{1 + \\beta} = \\frac57v_0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ea8e896e8ce4b', 'les_ad529bd15ce2c9', 'experiment', 4, 'activity', '{"activity":"rolling-race","title":"Race the shapes","params":{"height":1,"angle":30}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e2432948cccda4', 'les_ad529bd15ce2c9', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Bowling-ball skid distance, ABS braking and tire design all depend on this transition between sliding and rolling."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e158e04575b6d3', 'les_ad529bd15ce2c9', 1, 'practice', 'numeric', 2, 'A bowling ball is released sliding at 7 m/s with no spin. Find its final rolling speed.', '{"answer":5,"unit":"m/s"}', '[]', '$\frac57(7)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_43c2eec44ade46', 'les_ad529bd15ce2c9', 2, 'practice', 'numeric', 2, 'Find the friction force on a 2 kg solid disk rolling down a 30° incline.', '{"answer":3.27,"tolerance":0.01,"unit":"N"}', '[]', '$\frac13(2)(9.8)(0.5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9be02612277ef0', 'les_ad529bd15ce2c9', 3, 'practice', 'numeric', 3, 'What minimum μ_s lets a hoop roll without slipping on a 20° incline? Two decimal places.', '{"answer":0.18,"tolerance":0.01}', '[]', '$\frac12\tan 20° \approx 0.18$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1ea8e896e8ce4b', 'les_ad529bd15ce2c9', 4, 'review', 'multiple_choice', 3, 'For an object rolling without slipping, static friction does how much work?', '{"choices":["mgh","zero","½mv²","negative work"],"answer":1}', '[]', 'The contact point doesn''t slide.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ad529bd15ce2c9', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ad529bd15ce2c9', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: calc-rotational-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_29aba30bcca9cb', 'calc-rotational-energy', 'Rotational kinetic energy', 'Derive K_rot = ½Iω² by integrating over mass elements, and use energy conservation for rotating and swinging objects.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a6eaaf2705875e', 'les_29aba30bcca9cb', 1, 'Derive K = ½Iω² from ∫½v² dm with v = rω.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4b303355365519', 'les_29aba30bcca9cb', 2, 'Use energy conservation for rods and other objects swinging about a pivot.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5278141ee57e23', 'les_29aba30bcca9cb', 3, 'Use the center-of-mass height for gravitational energy.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a6eaaf2705875e', 'les_29aba30bcca9cb', 'learn', 1, 'definition', '{"term":"Derivation","body":"Each mass element moves at $v = r\\omega$, so $K = \\int\\frac12v^2\\,dm = \\frac12\\omega^2\\int r^2\\,dm = \\frac12I\\omega^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4b303355365519', 'les_29aba30bcca9cb', 'learn', 2, 'worked_example', '{"title":"A uniform 1.5 m rod pivoted at one end swings down from horizontal","steps":[{"latex":"mg\\tfrac L2 = \\tfrac12\\left(\\tfrac13mL^2\\right)\\omega^2","explanation":"Its center of mass drops L/2."},{"latex":"\\omega = \\sqrt{\\tfrac{3g}{L}} = \\sqrt{19.6} \\approx 4.43\\ \\text{rad/s}","explanation":""},{"latex":"v_{tip} = \\omega L = \\sqrt{3gL} \\approx 6.64\\ \\text{m/s}","explanation":"Faster than an object dropped 1.5 m (5.42 m/s)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5278141ee57e23', 'les_29aba30bcca9cb', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Flywheel energy storage, falling trees, and swinging gates all follow this energy bookkeeping."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a6eaaf2705875e', 'les_29aba30bcca9cb', 1, 'practice', 'numeric', 2, 'A uniform 0.6 m rod pivoted at one end swings down from horizontal. Find ω at the bottom, to two decimal places.', '{"answer":7,"tolerance":0.01,"unit":"rad/s"}', '[]', '$\sqrt{\frac{3(9.8)}{0.6}} = \sqrt{49}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4b303355365519', 'les_29aba30bcca9cb', 2, 'practice', 'numeric', 2, 'Find the kinetic energy of a 3 kg solid disk (R = 0.2 m) at 10 rad/s.', '{"answer":3,"unit":"J"}', '[]', '$\frac12\left(\frac12(3)(0.04)\right)(100)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5278141ee57e23', 'les_29aba30bcca9cb', 3, 'practice', 'multiple_choice', 2, 'For an object both moving and spinning, total kinetic energy is…', '{"choices":["½mv² only","½Iω² only","½Mv_cm² + ½I_cm ω²","Iω"],"answer":2}', '[]', 'Translation of the center of mass plus rotation about it.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ff9d66a0076577', 'les_29aba30bcca9cb', 4, 'review', 'multiple_choice', 3, 'A rod swinging from a pivot: its gravitational potential energy depends on the height of…', '{"choices":["its pivot","its tip","its center of mass","its lowest point"],"answer":2}', '[]', '$U = Mgy_{cm}$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_29aba30bcca9cb', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_29aba30bcca9cb', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_29aba30bcca9cb', (SELECT id FROM formulas WHERE slug = 'calculus-rotation'), 2);

-- Lesson: calc-rotational-kinematics
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4c290de1ca82fd', 'calc-rotational-kinematics', 'Rotational kinematics', 'Define angular velocity and acceleration as derivatives of angular position, and integrate non-constant angular accelerations.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fddb4f107a30d2', 'les_4c290de1ca82fd', 1, 'Compute ω = dθ/dt and α = dω/dt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e4cbbfb85ea809', 'les_4c290de1ca82fd', 2, 'Integrate α(t) and ω(t) with initial conditions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_695478dc920d36', 'les_4c290de1ca82fd', 3, 'Recognize when the constant-α equations apply.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fddb4f107a30d2', 'les_4c290de1ca82fd', 'learn', 1, 'definition', '{"term":"Angular derivatives","body":"With $\\theta$ in radians, $\\omega = \\frac{d\\theta}{dt}$ and $\\alpha = \\frac{d\\omega}{dt} = \\frac{d^2\\theta}{dt^2}$. Every linear-kinematics method carries over, with $\\theta$, $\\omega$ and $\\alpha$ in place of $x$, $v$ and $a$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e4cbbfb85ea809', 'les_4c290de1ca82fd', 'learn', 2, 'worked_example', '{"title":"θ(t) = 2t³ − t² (radians)","steps":[{"latex":"\\omega = 6t^2 - 2t,\\ \\alpha = 12t - 2","explanation":""},{"latex":"t = 1:\\ \\omega = 4\\ \\text{rad/s},\\ \\alpha = 10\\ \\text{rad/s}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_695478dc920d36', 'les_4c290de1ca82fd', 'learn', 3, 'worked_example', '{"title":"A wheel starts from rest with α(t) = 4t rad/s²","steps":[{"latex":"\\omega = 2t^2,\\ \\theta = \\tfrac23 t^3","explanation":""},{"latex":"t = 3:\\ \\omega = 18\\ \\text{rad/s},\\ \\theta = 18\\ \\text{rad}","explanation":"About 2.9 revolutions."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8eafefa53044ce', 'les_4c290de1ca82fd', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Hard drives and centrifuges spin up with programmed α(t) profiles to limit stress, and wind turbines'' controllers track ω(t) continuously."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fddb4f107a30d2', 'les_4c290de1ca82fd', 1, 'practice', 'numeric', 2, 'θ(t) = t³ − 3t (rad). When is the object momentarily not rotating? (t > 0)', '{"answer":1,"unit":"s"}', '[]', '$\omega = 3t^2 - 3 = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e4cbbfb85ea809', 'les_4c290de1ca82fd', 2, 'practice', 'numeric', 2, 'A disk at 10 rad/s has α = −2t rad/s². Find ω at t = 2 s.', '{"answer":6,"unit":"rad/s"}', '[]', '$\omega = 10 - t^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_695478dc920d36', 'les_4c290de1ca82fd', 3, 'practice', 'numeric', 3, 'For that disk, through what angle does it turn before stopping? Give one decimal place.', '{"answer":21.1,"tolerance":0.1,"unit":"rad"}', '[]', 'Stops at $t = \sqrt{10}$; $\theta = 10t - \frac{t^3}{3} = \frac{20}{3}\sqrt{10} \approx 21.1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8eafefa53044ce', 'les_4c290de1ca82fd', 4, 'review', 'multiple_choice', 3, 'The equation θ = ω₀t + ½αt² applies when…', '{"choices":["always","α is constant","ω is constant","α = 4t"],"answer":1}', '[]', 'It''s derived by integrating a constant α.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4c290de1ca82fd', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4c290de1ca82fd', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: calc-rotational-second-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f1d37554ae26b7', 'calc-rotational-second-law', 'Newton''s second law in rotational form', 'Apply τ = Iα to extended objects using calculated rotational inertias, including rods pivoted at one end and massive pulleys.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_591f574e8dec5c', 'les_f1d37554ae26b7', 1, 'Apply τ_net = Iα with I about the actual axis.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_783b8f5bf3d402', 'les_f1d37554ae26b7', 2, 'Find the angular acceleration of a rod released from horizontal.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eb712601c194f8', 'les_f1d37554ae26b7', 3, 'Combine linear and rotational equations for pulley systems.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_591f574e8dec5c', 'les_f1d37554ae26b7', 'learn', 1, 'definition', '{"term":"The law","body":"$\\sum\\tau = I\\alpha$ about a fixed axis (or about the center of mass). Gravity acts at the center of mass, so its torque on an extended object is $mg$ times the horizontal distance from the pivot to the center of mass."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_783b8f5bf3d402', 'les_f1d37554ae26b7', 'learn', 2, 'worked_example', '{"title":"A uniform 1.5 m rod pivoted at one end is released from horizontal","steps":[{"latex":"\\tau = mg\\tfrac L2,\\ I = \\tfrac13 mL^2","explanation":""},{"latex":"\\alpha = \\tfrac{3g}{2L} = \\tfrac{3(9.8)}{2(1.5)} = 9.8\\ \\text{rad/s}^2","explanation":""},{"latex":"a_{tip} = \\alpha L = 1.5g = 14.7\\ \\text{m/s}^2","explanation":"Faster than free fall: a coin on the tip gets left behind."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eb712601c194f8', 'les_f1d37554ae26b7', 'learn', 3, 'callout', '{"tone":"tip","title":"Systems","body":"For a mass hanging from a pulley with rotational inertia $I$: $mg - T = ma$, $TR = I\\alpha$ and $a = R\\alpha$. Then $a = \\frac{mg}{m + I/R^2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_34e0f1af10d4f7', 'les_f1d37554ae26b7', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Falling chimneys break apart because the top wants a larger tangential acceleration than free fall allows; trebuchets exploit the same physics."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_591f574e8dec5c', 'les_f1d37554ae26b7', 1, 'practice', 'numeric', 2, 'A uniform 2 m rod pivoted at one end is released horizontal. Find α.', '{"answer":7.35,"unit":"rad/s²"}', '[]', '$\frac{3(9.8)}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_783b8f5bf3d402', 'les_f1d37554ae26b7', 2, 'practice', 'numeric', 3, 'A 1 kg mass hangs from a light string wrapped around a pulley with I = 0.02 kg·m² and R = 0.1 m. Find a.', '{"answer":3.27,"tolerance":0.01,"unit":"m/s²"}', '[]', '$\frac{9.8}{1 + 2} \approx 3.27$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eb712601c194f8', 'les_f1d37554ae26b7', 3, 'practice', 'multiple_choice', 2, 'Where does gravity''s torque on a uniform rod act?', '{"choices":["at the pivot","at the center of mass","at the free end","everywhere equally"],"answer":1}', '[]', 'Summing $\int x\,g\,dm$ gives $Mg\,x_{cm}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_34e0f1af10d4f7', 'les_f1d37554ae26b7', 4, 'review', 'multiple_choice', 3, 'As a released rod swings down to vertical, its angular acceleration…', '{"choices":["stays constant","decreases to zero","increases","reverses"],"answer":1}', '[]', 'The lever arm, $\frac L2\cos\theta$, shrinks to zero.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f1d37554ae26b7', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f1d37554ae26b7', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f1d37554ae26b7', (SELECT id FROM formulas WHERE slug = 'calculus-rotation'), 2);

-- Lesson: calc-shm-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_dfd64d9dffb029', 'calc-shm-energy', 'Energy of simple harmonic oscillators', 'Show that total energy is constant in SHM using the sinusoidal solution, find speeds from energy, and compute time-averaged kinetic and potential energy.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ea6dff6afe7d48', 'les_dfd64d9dffb029', 1, 'Show K + U = ½kA² is constant using x(t) and v(t).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_904538ead6d1ae', 'les_dfd64d9dffb029', 2, 'Find v at any x from energy conservation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_287a1c87652827', 'les_dfd64d9dffb029', 3, 'Show the time averages of K and U are each ½E.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ea6dff6afe7d48', 'les_dfd64d9dffb029', 'learn', 1, 'definition', '{"term":"Constant energy","body":"With $x = A\\cos\\omega t$ and $v = -A\\omega\\sin\\omega t$: $U = \\frac12kA^2\\cos^2\\omega t$ and $K = \\frac12mA^2\\omega^2\\sin^2\\omega t = \\frac12kA^2\\sin^2\\omega t$, since $m\\omega^2 = k$. Their sum is $\\frac12kA^2$ at every instant."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_904538ead6d1ae', 'les_dfd64d9dffb029', 'learn', 2, 'definition', '{"term":"Averages","body":"Over a full cycle, $\\cos^2$ and $\\sin^2$ each average to $\\frac12$, so $\\langle K\\rangle = \\langle U\\rangle = \\frac12E$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_287a1c87652827', 'les_dfd64d9dffb029', 'learn', 3, 'worked_example', '{"title":"k = 50 N/m, A = 0.2 m","steps":[{"latex":"E = \\tfrac12(50)(0.04) = 1\\ \\text{J}","explanation":""},{"latex":"\\text{at}\\ x = 0.1:\\ U = 0.25\\ \\text{J},\\ K = 0.75\\ \\text{J}","explanation":""},{"latex":"K = U\\ \\text{at}\\ x = \\tfrac{A}{\\sqrt2} \\approx 0.141\\ \\text{m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_30eabaa5693d4c', 'les_dfd64d9dffb029', 'experiment', 4, 'activity', '{"activity":"spring-oscillator","title":"Energy bars through a cycle","params":{"mass":1,"k":50,"amplitude":0.2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_92a2b902bd0d55', 'les_dfd64d9dffb029', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"The equipartition of energy in vibrating molecules, and the energy budget of tuned mass dampers in skyscrapers."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ea6dff6afe7d48', 'les_dfd64d9dffb029', 1, 'practice', 'numeric', 2, 'A 2 kg oscillator has ω = 3 rad/s and A = 0.4 m. Find its total energy.', '{"answer":1.44,"tolerance":0.001,"unit":"J"}', '[]', '$\frac12m\omega^2A^2 = \frac12(2)(9)(0.16)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_904538ead6d1ae', 'les_dfd64d9dffb029', 2, 'practice', 'numeric', 2, 'For that oscillator, find the speed at x = 0.2 m, to two decimal places.', '{"answer":1.04,"tolerance":0.01,"unit":"m/s"}', '[]', '$3\sqrt{0.16 - 0.04} \approx 1.04$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_287a1c87652827', 'les_dfd64d9dffb029', 3, 'practice', 'multiple_choice', 2, 'Averaged over one period, the kinetic energy equals…', '{"choices":["E","½E","0","2E"],"answer":1}', '[]', '$\langle\sin^2\rangle = \frac12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_30eabaa5693d4c', 'les_dfd64d9dffb029', 4, 'review', 'multiple_choice', 3, 'Doubling ω (same A and m) multiplies the energy by…', '{"choices":["2","4","√2","1"],"answer":1}', '[]', '$E = \frac12m\omega^2A^2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_dfd64d9dffb029', (SELECT id FROM concepts WHERE slug = 'simple-harmonic-motion'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_dfd64d9dffb029', (SELECT id FROM formulas WHERE slug = 'work-energy'), 1);

-- Lesson: calc-shm-period
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a0f019800861f0', 'calc-shm-period', 'Frequency and period of SHM', 'Read ω directly from any SHM differential equation, and find periods of springs, torsion pendulums and other oscillators.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_63b34cab1a99e1', 'les_a0f019800861f0', 1, 'Read ω from equations of the form d²x/dt² = −ω²x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9bfa661ab87f38', 'les_a0f019800861f0', 2, 'Compute periods for mass–spring systems, including vertical springs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3ebebba4dd2e95', 'les_a0f019800861f0', 3, 'Compute periods for torsion pendulums, T = 2π√(I/κ).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_63b34cab1a99e1', 'les_a0f019800861f0', 'learn', 1, 'definition', '{"term":"The recipe","body":"Write Newton''s second law for a small displacement, rearrange to $\\ddot q = -C q$, and read off $\\omega = \\sqrt C$, $T = \\frac{2\\pi}{\\omega}$, $f = \\frac1T$. The period never depends on amplitude for true SHM."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9bfa661ab87f38', 'les_a0f019800861f0', 'learn', 2, 'worked_example', '{"title":"Two oscillators","steps":[{"latex":"\\ddot x = -\\tfrac km x","explanation":"Spring: a 0.5 kg mass, k = 200 N/m, horizontal or vertical."},{"latex":"T = 2\\pi\\sqrt{\\tfrac{0.5}{200}} \\approx 0.314\\ \\text{s}","explanation":""},{"latex":"I\\ddot\\theta = -\\kappa\\theta","explanation":"Torsion pendulum: I = 0.02 kg·m², κ = 0.5 N·m/rad."},{"latex":"T = 2\\pi\\sqrt{\\tfrac{0.02}{0.5}} \\approx 1.26\\ \\text{s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ebebba4dd2e95', 'les_a0f019800861f0', 'experiment', 3, 'activity', '{"activity":"spring-oscillator","title":"Period depends on m and k, not amplitude","params":{"mass":0.5,"k":200,"amplitude":0.2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6d7fc0694d360f', 'les_a0f019800861f0', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Quartz watches count a crystal''s oscillations, and the period of a torsion pendulum measures the moment of inertia of odd-shaped objects."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_63b34cab1a99e1', 'les_a0f019800861f0', 1, 'practice', 'numeric', 2, 'Find ω for d²x/dt² = −16x.', '{"answer":4,"unit":"rad/s"}', '[]', '$\sqrt{16}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9bfa661ab87f38', 'les_a0f019800861f0', 2, 'practice', 'numeric', 2, 'A mass on a vertical spring stretches it 0.1 m at equilibrium. Find the period of oscillation, to two decimal places.', '{"answer":0.63,"tolerance":0.01,"unit":"s"}', '[]', '$\frac km = \frac g{0.1}$, so $T = 2\pi\sqrt{\frac{0.1}{9.8}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3ebebba4dd2e95', 'les_a0f019800861f0', 3, 'practice', 'multiple_choice', 2, 'Hanging a spring vertically instead of horizontally changes its period by…', '{"choices":["a factor of g","nothing","doubling","halving"],"answer":1}', '[]', 'Gravity only shifts the equilibrium.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6d7fc0694d360f', 'les_a0f019800861f0', 4, 'review', 'multiple_choice', 3, 'Four times the mass on the same spring gives…', '{"choices":["4× the period","2× the period","½ the period","the same period"],"answer":1}', '[]', '$T \propto \sqrt m$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a0f019800861f0', (SELECT id FROM concepts WHERE slug = 'simple-harmonic-motion'));

-- Lesson: calc-shm-representing
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6c6e26003f1196', 'calc-shm-representing', 'Representing and analyzing SHM', 'Differentiate sinusoidal position functions to get velocity and acceleration, read phase relationships from graphs, and evaluate the motion at any instant.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dd603b0fdd58ae', 'les_6c6e26003f1196', 1, 'Differentiate x = A sin(ωt + φ) to get v and a.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_287cc4fd4dd598', 'les_6c6e26003f1196', 2, 'Explain the 90° phase lead of v and the 180° phase of a relative to x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_72abe61b165c42', 'les_6c6e26003f1196', 3, 'Evaluate position, velocity and acceleration at a given time.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dd603b0fdd58ae', 'les_6c6e26003f1196', 'learn', 1, 'definition', '{"term":"Derivatives","body":"If $x = A\\sin(\\omega t + \\phi)$, then $v = A\\omega\\cos(\\omega t + \\phi)$ and $a = -A\\omega^2\\sin(\\omega t + \\phi) = -\\omega^2x$. Velocity leads position by a quarter cycle; acceleration is exactly opposite to position."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_287cc4fd4dd598', 'les_6c6e26003f1196', 'learn', 2, 'worked_example', '{"title":"x(t) = 0.1 sin(4t + π/6) m, at t = 0","steps":[{"latex":"x = 0.1\\sin\\tfrac\\pi6 = 0.05\\ \\text{m}","explanation":""},{"latex":"v = 0.4\\cos\\tfrac\\pi6 \\approx 0.346\\ \\text{m/s}","explanation":""},{"latex":"a = -16(0.05) = -0.8\\ \\text{m/s}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_72abe61b165c42', 'les_6c6e26003f1196', 'experiment', 3, 'activity', '{"activity":"sinusoid","title":"Amplitude, period and phase shift"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7958f8c288355b', 'les_6c6e26003f1196', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers read phase lags between displacement and force to diagnose vibrating machinery; AC circuits use the same phase language."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dd603b0fdd58ae', 'les_6c6e26003f1196', 1, 'practice', 'numeric', 2, 'x(t) = 0.3cos(2t) m. Find v at t = π/4 s.', '{"answer":-0.6,"unit":"m/s"}', '[]', '$v = -0.6\sin(2t)$ and $\sin\frac\pi2 = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_287cc4fd4dd598', 'les_6c6e26003f1196', 2, 'practice', 'numeric', 2, 'For x(t) = 0.3cos(2t), find the maximum acceleration.', '{"answer":1.2,"unit":"m/s²"}', '[]', '$A\omega^2 = 0.3(4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_72abe61b165c42', 'les_6c6e26003f1196', 3, 'practice', 'multiple_choice', 2, 'When x is at its maximum, v is…', '{"choices":["maximum","zero","minimum (most negative)","equal to x"],"answer":1}', '[]', 'A turning point.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7958f8c288355b', 'les_6c6e26003f1196', 4, 'review', 'multiple_choice', 3, 'Compared with position, acceleration in SHM is…', '{"choices":["in phase","90° ahead","180° out of phase","unrelated"],"answer":2}', '[]', '$a = -\omega^2x$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_6c6e26003f1196', (SELECT id FROM concepts WHERE slug = 'simple-harmonic-motion'));

-- Lesson: calc-spring-forces
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9d3a618e96823b', 'calc-spring-forces', 'Spring forces', 'Use Hooke''s law for horizontal and vertical springs, derive spring potential energy by integration, and analyze spring launchers.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_65ed46a1dafba9', 'les_9d3a618e96823b', 1, 'Apply F = −kx, including the new equilibrium of a vertical spring.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_89ca329610414a', 'les_9d3a618e96823b', 2, 'Derive U = ½kx² from the spring force by integration.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_089e0fa5dc6e3e', 'les_9d3a618e96823b', 3, 'Use energy conservation for spring launchers.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_65ed46a1dafba9', 'les_9d3a618e96823b', 'learn', 1, 'definition', '{"term":"Hooke''s law and energy","body":"An ideal spring exerts $F = -kx$. Its potential energy is $U = -\\int_0^x(-kx'')\\,dx'' = \\frac12kx^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_89ca329610414a', 'les_9d3a618e96823b', 'learn', 2, 'definition', '{"term":"Vertical springs","body":"A hanging mass stretches the spring to a new equilibrium $y_0 = \\frac{mg}{k}$. Measured from there, gravity and the extra spring force combine into a pure $-ky$: the motion is the same as horizontal, just shifted."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_089e0fa5dc6e3e', 'les_9d3a618e96823b', 'learn', 3, 'worked_example', '{"title":"1 kg on a 100 N/m spring","steps":[{"latex":"y_0 = \\tfrac{1(9.8)}{100} = 0.098\\ \\text{m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7853bc540dc689', 'les_9d3a618e96823b', 'learn', 4, 'worked_example', '{"title":"A 500 N/m launcher is compressed 0.1 m and fires a 0.2 kg ball horizontally","steps":[{"latex":"\\tfrac12(500)(0.1^2) = \\tfrac12(0.2)v^2","explanation":""},{"latex":"v = 5\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0f94c2265e9482', 'les_9d3a618e96823b', 'experiment', 5, 'activity', '{"activity":"work-integral","title":"Spring work is a triangle","params":{"law":"spring","k":2,"x1":0,"x2":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de84291619b8d5', 'les_9d3a618e96823b', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pinball plungers, car suspensions, trampolines and atomic-force microscope cantilevers."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_65ed46a1dafba9', 'les_9d3a618e96823b', 1, 'practice', 'numeric', 2, 'A 0.5 kg mass stretches a vertical spring 0.049 m. Find k.', '{"answer":100,"unit":"N/m"}', '[]', '$\frac{mg}{y_0}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_89ca329610414a', 'les_9d3a618e96823b', 2, 'practice', 'numeric', 2, 'How much energy is stored in a 400 N/m spring compressed 0.05 m?', '{"answer":0.5,"unit":"J"}', '[]', '$\frac12(400)(0.0025)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_089e0fa5dc6e3e', 'les_9d3a618e96823b', 3, 'practice', 'numeric', 3, 'A 2 kg block moving at 3 m/s hits a 450 N/m spring. Find the maximum compression.', '{"answer":0.2,"unit":"m"}', '[]', '$\frac12(2)(9) = \frac12(450)x^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7853bc540dc689', 'les_9d3a618e96823b', 4, 'review', 'multiple_choice', 3, 'Compressing a spring twice as far takes ___ the work.', '{"choices":["2 times","4 times","√2 times","the same"],"answer":1}', '[]', '$U \propto x^2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9d3a618e96823b', (SELECT id FROM concepts WHERE slug = 'energy'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9d3a618e96823b', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: calc-torque-work
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8e8aee1be7016d', 'calc-torque-work', 'Torque and work', 'Compute the work done by torques that vary with angle as W = ∫τ dθ, including torsion springs, and relate rotational power to τω.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_04fc32deeaf499', 'les_8e8aee1be7016d', 1, 'Compute W = ∫τ dθ for torques that vary with angle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7777824235dfd2', 'les_8e8aee1be7016d', 2, 'Find the energy stored in a torsion spring, ½κθ².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a4dd604f8c2dec', 'les_8e8aee1be7016d', 3, 'Use P = τω and the rotational work–energy theorem.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04fc32deeaf499', 'les_8e8aee1be7016d', 'learn', 1, 'definition', '{"term":"Work by a varying torque","body":"As a torque turns an object through $d\\theta$, it does work $dW = \\tau\\,d\\theta$, so $W = \\int_{\\theta_1}^{\\theta_2}\\tau\\,d\\theta$. Power is $P = \\frac{dW}{dt} = \\tau\\omega$, and $W_{net} = \\Delta(\\frac12I\\omega^2)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7777824235dfd2', 'les_8e8aee1be7016d', 'learn', 2, 'worked_example', '{"title":"τ(θ) = 2θ N·m from θ = 0 to π","steps":[{"latex":"W = \\int_0^\\pi 2\\theta\\,d\\theta = \\pi^2 \\approx 9.87\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a4dd604f8c2dec', 'les_8e8aee1be7016d', 'learn', 3, 'definition', '{"term":"Torsion springs","body":"A twisted wire or coil exerts $\\tau = -\\kappa\\theta$. Twisting it to angle $\\theta$ stores $\\int_0^\\theta\\kappa\\theta''\\,d\\theta'' = \\frac12\\kappa\\theta^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fef0779ae9cc20', 'les_8e8aee1be7016d', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Mousetraps, clothespins and mechanical watch balance springs are torsion springs; Cavendish measured G with a torsion balance."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_04fc32deeaf499', 'les_8e8aee1be7016d', 1, 'practice', 'numeric', 2, 'A torsion spring (κ = 0.8 N·m/rad) is twisted through 1.5 rad. Find the stored energy.', '{"answer":0.9,"unit":"J"}', '[]', '$\frac12(0.8)(2.25)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7777824235dfd2', 'les_8e8aee1be7016d', 2, 'practice', 'numeric', 3, 'τ(θ) = 3θ² N·m acts on a wheel (I = 0.5 kg·m²) from rest, from θ = 0 to 2 rad. Find ω.', '{"answer":5.66,"tolerance":0.01,"unit":"rad/s"}', '[]', '$W = \theta^3 = 8$ J $= \frac12(0.5)\omega^2$, so $\omega = \sqrt{32}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a4dd604f8c2dec', 'les_8e8aee1be7016d', 3, 'practice', 'multiple_choice', 2, 'A torque opposes a wheel''s rotation. The work it does is…', '{"choices":["positive","negative","zero","infinite"],"answer":1}', '[]', '$\tau$ and $d\theta$ have opposite signs.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fef0779ae9cc20', 'les_8e8aee1be7016d', 4, 'review', 'multiple_choice', 3, 'On a τ–θ graph, the work done is…', '{"choices":["the slope","the area under the curve","the maximum torque","τ times ω"],"answer":1}', '[]', '$W = \int\tau\,d\theta$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8e8aee1be7016d', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8e8aee1be7016d', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: calc-vectors-1d
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a3b75ed2f552a4', 'calc-vectors-1d', 'Scalars and vectors in one dimension', 'Represent one-dimensional vectors with a sign and a unit vector, and distinguish displacement from distance and velocity from speed, including as integrals.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b235ea8a435a69', 'les_a3b75ed2f552a4', 1, 'Write 1D vectors as components times the unit vector î.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a2a32185e0e0a3', 'les_a3b75ed2f552a4', 2, 'Distinguish displacement and distance, velocity and speed.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2acce195522bec', 'les_a3b75ed2f552a4', 3, 'Express displacement as ∫v dt and distance as ∫|v| dt.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b235ea8a435a69', 'les_a3b75ed2f552a4', 'learn', 1, 'definition', '{"term":"Vectors on a line","body":"In one dimension a vector is a signed number times the unit vector $\\hat\\imath$: $\\vec v = -3\\,\\hat\\imath$ m/s points in −x. Scalars such as mass, time, speed and distance have no direction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a2a32185e0e0a3', 'les_a3b75ed2f552a4', 'learn', 2, 'definition', '{"term":"Displacement and distance","body":"Displacement $\\Delta x = x_f - x_i = \\int v\\,dt$ depends only on the endpoints. Distance $\\int|v|\\,dt$ counts every meter traveled. Average velocity is $\\frac{\\Delta x}{\\Delta t}$; average speed is $\\frac{\\text{distance}}{\\Delta t}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2acce195522bec', 'les_a3b75ed2f552a4', 'learn', 3, 'worked_example', '{"title":"Walk 10 m east in 2 s, then 4 m west in 2 s","steps":[{"latex":"\\Delta x = +10 - 4 = +6\\ \\text{m},\\ d = 14\\ \\text{m}","explanation":""},{"latex":"\\bar v = \\tfrac{6}{4} = 1.5\\ \\text{m/s}","explanation":"Average velocity."},{"latex":"\\tfrac{14}{4} = 3.5\\ \\text{m/s}","explanation":"Average speed."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1798fc1eee4ea4', 'les_a3b75ed2f552a4', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"A runner who finishes a 400 m lap where they started has zero displacement and zero average velocity, but a very nonzero average speed."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b235ea8a435a69', 'les_a3b75ed2f552a4', 1, 'practice', 'numeric', 1, 'An object moves from x = −3 m to x = 5 m in 4 s. Find its average velocity.', '{"answer":2,"unit":"m/s"}', '[]', '$\frac{8}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a2a32185e0e0a3', 'les_a3b75ed2f552a4', 2, 'practice', 'numeric', 2, 'v(t) = 3 − t from 0 to 6 s. Find the displacement.', '{"answer":0,"unit":"m"}', '[]', '$3t - \frac{t^2}{2}$ at 6 is $18 - 18$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2acce195522bec', 'les_a3b75ed2f552a4', 3, 'practice', 'numeric', 2, 'For the same motion, find the distance traveled.', '{"answer":9,"unit":"m"}', '[]', '4.5 m forward (0–3 s), then 4.5 m back.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1798fc1eee4ea4', 'les_a3b75ed2f552a4', 4, 'review', 'multiple_choice', 3, 'Which can be negative?', '{"choices":["speed","distance","displacement","mass"],"answer":2}', '[]', 'Displacement has a direction.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a3b75ed2f552a4', (SELECT id FROM concepts WHERE slug = 'kinematics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a3b75ed2f552a4', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: calc-work-energy-theorem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_32ada1fbff05f3', 'calc-work-energy-theorem', 'Translational kinetic energy', 'Derive the work–energy theorem from Newton''s second law with calculus, and use it to find speeds after variable forces act.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e5869e54ce898d', 'les_32ada1fbff05f3', 1, 'Derive W_net = ΔK from F = m dv/dt using a = v dv/dx.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5d86910e8cf7d8', 'les_32ada1fbff05f3', 2, 'Use the theorem to find speeds after variable forces act.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a76fe34a3d16ac', 'les_32ada1fbff05f3', 3, 'Explain why kinetic energy is always nonnegative and frame-dependent.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e5869e54ce898d', 'les_32ada1fbff05f3', 'learn', 1, 'definition', '{"term":"Derivation","body":"By the chain rule, $a = \\frac{dv}{dt} = \\frac{dv}{dx}\\frac{dx}{dt} = v\\frac{dv}{dx}$. So $W_{net} = \\int F_{net}\\,dx = \\int mv\\frac{dv}{dx}\\,dx = \\int_{v_1}^{v_2} mv\\,dv = \\frac12mv_2^2 - \\frac12mv_1^2$. Kinetic energy $K = \\frac12mv^2$ is exactly what net work changes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d86910e8cf7d8', 'les_32ada1fbff05f3', 'learn', 2, 'worked_example', '{"title":"F = 3x² newtons pushes a 2 kg block from rest from x = 0 to 2 m (no friction)","steps":[{"latex":"W = \\int_0^2 3x^2\\,dx = 8\\ \\text{J}","explanation":""},{"latex":"\\tfrac12(2)v^2 = 8 \\Rightarrow v \\approx 2.83\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a76fe34a3d16ac', 'les_32ada1fbff05f3', 'learn', 3, 'callout', '{"tone":"note","title":"Frames","body":"Kinetic energy depends on the reference frame: a passenger has zero K relative to the train but plenty relative to the ground. The work–energy theorem holds in any single inertial frame."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3dea3a84d57221', 'les_32ada1fbff05f3', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Braking distance grows with v², because brakes must remove all the kinetic energy: doubling speed quadruples the stopping distance."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e5869e54ce898d', 'les_32ada1fbff05f3', 1, 'practice', 'numeric', 2, 'A net force F = 10 − 2x (N) acts on a 1 kg cart from rest, from x = 0 to 5 m. Find its final speed, to two decimal places.', '{"answer":7.07,"tolerance":0.01,"unit":"m/s"}', '[]', '$W = 50 - 25 = 25$ J $= \frac12v^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5d86910e8cf7d8', 'les_32ada1fbff05f3', 2, 'practice', 'numeric', 2, 'A 1500 kg car brakes from 20 m/s to rest. Find the work done by the brakes.', '{"answer":-300000,"unit":"J"}', '[]', '$-\frac12(1500)(400)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a76fe34a3d16ac', 'les_32ada1fbff05f3', 3, 'practice', 'multiple_choice', 2, 'Doubling speed multiplies stopping distance (same braking force) by…', '{"choices":["2","4","√2","8"],"answer":1}', '[]', '$Fd = \frac12mv^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3dea3a84d57221', 'les_32ada1fbff05f3', 4, 'review', 'multiple_choice', 3, 'A net force does negative work on an object. Its speed…', '{"choices":["increases","decreases","stays the same","becomes negative"],"answer":1}', '[]', '$\Delta K < 0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_32ada1fbff05f3', (SELECT id FROM concepts WHERE slug = 'energy'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_32ada1fbff05f3', (SELECT id FROM formulas WHERE slug = 'work-energy'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_32ada1fbff05f3', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 2);

-- Lesson: calc-work-variable-forces
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_99852e070b9cfa', 'calc-work-variable-forces', 'Work done by variable forces', 'Compute work as the integral of force over displacement, including spring forces and forces given by functions or graphs.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_37a34bfae36087', 'les_99852e070b9cfa', 1, 'Compute W = ∫F dx for forces that vary with position.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_43621907f19023', 'les_99852e070b9cfa', 2, 'Derive the work to stretch a spring, ½kx².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_73b76785d4f3fa', 'les_99852e070b9cfa', 3, 'Interpret work as the signed area under an F–x graph.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_37a34bfae36087', 'les_99852e070b9cfa', 'learn', 1, 'definition', '{"term":"Work as an integral","body":"Cut the path into tiny pieces $dx$, each with nearly constant force: $dW = F\\,dx$. Adding them up gives $W = \\int_{x_1}^{x_2} F(x)\\,dx$, the area under the force–position graph. In 3D, $W = \\int \\vec F\\cdot d\\vec r$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_43621907f19023', 'les_99852e070b9cfa', 'learn', 2, 'worked_example', '{"title":"Stretching a spring from 0 to x","steps":[{"latex":"W = \\int_0^x kx''\\,dx'' = \\tfrac12 kx^2","explanation":"Applied force F = kx."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_73b76785d4f3fa', 'les_99852e070b9cfa', 'learn', 3, 'worked_example', '{"title":"F(x) = 3x² newtons from x = 0 to 2 m","steps":[{"latex":"W = \\int_0^2 3x^2\\,dx = x^3\\Big|_0^2 = 8\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f16cf601c54676', 'les_99852e070b9cfa', 'experiment', 4, 'activity', '{"activity":"work-integral","title":"Work is the area under F(x)","params":{"law":"square","k":3,"x1":0,"x2":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c67b27242ea511', 'les_99852e070b9cfa', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Switch to the decreasing force and slide x₂ past 2.5 m: the force turns negative and the shaded area below the axis subtracts from the work."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_25e61e91bcdae8', 'les_99852e070b9cfa', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Archery bows, bungee cords and car suspensions are rated by their force–draw curves; the area gives the stored energy."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_37a34bfae36087', 'les_99852e070b9cfa', 1, 'practice', 'numeric', 2, 'F(x) = 5 − 2x newtons. Find the work from x = 0 to 3 m.', '{"answer":6,"unit":"J"}', '[]', '$5x - x^2$ from 0 to 3.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_43621907f19023', 'les_99852e070b9cfa', 2, 'practice', 'numeric', 2, 'How much work stretches a 200 N/m spring from 0.1 m to 0.3 m?', '{"answer":8,"unit":"J"}', '[]', '$\frac12(200)(0.09 - 0.01)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_73b76785d4f3fa', 'les_99852e070b9cfa', 3, 'practice', 'numeric', 3, 'F(x) = 4/x² newtons. Find the work from x = 1 to 4 m.', '{"answer":3,"unit":"J"}', '[]', '$\left[-\frac4x\right]_1^4 = -1 + 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f16cf601c54676', 'les_99852e070b9cfa', 4, 'review', 'multiple_choice', 3, 'Stretching a spring from 0 to 2x takes how much work compared with 0 to x?', '{"choices":["the same","twice as much","four times as much","half as much"],"answer":2}', '[]', '$W \propto x^2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_99852e070b9cfa', (SELECT id FROM concepts WHERE slug = 'energy'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_99852e070b9cfa', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: physical-pendulum
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d53641e043b913', 'physical-pendulum', 'Simple and physical pendulums', 'Derive the small-angle equation of motion for simple and physical pendulums from τ = Iα, and compute their periods.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0f33ce982dadcd', 'les_d53641e043b913', 1, 'Derive d²θ/dt² = −(g/L)θ for a simple pendulum using sin θ ≈ θ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d9cdee85bf47e6', 'les_d53641e043b913', 2, 'Derive T = 2π√(I/(mgd)) for a physical pendulum.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2e92118cd3110c', 'les_d53641e043b913', 3, 'Compute periods for rods, hoops and other extended objects.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0f33ce982dadcd', 'les_d53641e043b913', 'learn', 1, 'definition', '{"term":"Simple pendulum","body":"Gravity''s torque about the pivot is $-mgL\\sin\\theta$ and $I = mL^2$, so $mL^2\\ddot\\theta = -mgL\\sin\\theta$. For small angles, $\\sin\\theta \\approx \\theta$: $\\ddot\\theta = -\\frac gL\\theta$, which is SHM with $\\omega = \\sqrt{\\frac gL}$ and $T = 2\\pi\\sqrt{\\frac Lg}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d9cdee85bf47e6', 'les_d53641e043b913', 'learn', 2, 'definition', '{"term":"Physical pendulum","body":"An extended object pivoting a distance $d$ from its center of mass: $I\\ddot\\theta = -mgd\\sin\\theta \\approx -mgd\\,\\theta$, so $T = 2\\pi\\sqrt{\\frac{I}{mgd}}$, where $I$ is about the pivot."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2e92118cd3110c', 'les_d53641e043b913', 'learn', 3, 'worked_example', '{"title":"A uniform 1 m rod swinging from one end","steps":[{"latex":"I = \\tfrac13 mL^2,\\ d = \\tfrac L2","explanation":""},{"latex":"T = 2\\pi\\sqrt{\\tfrac{2L}{3g}} \\approx 1.64\\ \\text{s}","explanation":"Faster than a 1 m simple pendulum (2.01 s)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b3526a926883b6', 'les_d53641e043b913', 'learn', 4, 'worked_example', '{"title":"A hoop of radius 0.5 m hanging on a nail at its rim","steps":[{"latex":"I = MR^2 + MR^2 = 2MR^2,\\ d = R","explanation":"Parallel-axis theorem."},{"latex":"T = 2\\pi\\sqrt{\\tfrac{2R}{g}} \\approx 2.01\\ \\text{s}","explanation":"The same as a simple pendulum of length 2R."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7873fc49c84fd6', 'les_d53641e043b913', 'experiment', 5, 'activity', '{"activity":"pendulum","title":"The simple pendulum for comparison","params":{"planet":"earth","length":1,"amplitude":10}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_211a18fafcb946', 'les_d53641e043b913', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Walking legs swing roughly as physical pendulums, which sets natural walking pace; pendulum clocks use compensated physical pendulums."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0f33ce982dadcd', 'les_d53641e043b913', 1, 'practice', 'numeric', 2, 'A uniform 0.6 m rod swings from one end. Find its period, to two decimal places.', '{"answer":1.27,"tolerance":0.01,"unit":"s"}', '[]', '$2\pi\sqrt{\frac{2(0.6)}{3(9.8)}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d9cdee85bf47e6', 'les_d53641e043b913', 2, 'practice', 'numeric', 3, 'A meter stick pivots 0.25 m from its center. Find its period, to two decimal places.', '{"answer":1.53,"tolerance":0.01,"unit":"s"}', '[]', '$I = \frac{1}{12}m + m(0.0625)$; $T = 2\pi\sqrt{\frac{0.14583}{9.8(0.25)}} \approx 1.53$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2e92118cd3110c', 'les_d53641e043b913', 3, 'practice', 'multiple_choice', 2, 'The small-angle approximation for pendulums uses…', '{"choices":["cos θ ≈ θ","sin θ ≈ θ","tan θ ≈ 1","θ ≈ 0 exactly"],"answer":1}', '[]', 'Valid for θ under about 15°.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b3526a926883b6', 'les_d53641e043b913', 4, 'review', 'multiple_choice', 3, 'A physical pendulum''s period does NOT depend on…', '{"choices":["its mass, for a given shape","its shape","g","the pivot location"],"answer":0}', '[]', 'Mass cancels in I/(md).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d53641e043b913', (SELECT id FROM concepts WHERE slug = 'simple-harmonic-motion'));

-- Lesson: resistive-forces-terminal-velocity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ba144649758f7f', 'resistive-forces-terminal-velocity', 'Resistive forces and terminal velocity', 'Model drag forces proportional to v and v², solve the differential equation for falling with linear drag, and find terminal velocity and the time constant.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f121d495e0918d', 'les_ba144649758f7f', 1, 'Write Newton''s second law with drag: m dv/dt = mg − bv.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_01dd606cca8ab6', 'les_ba144649758f7f', 2, 'Solve it: v(t) = v_T(1 − e^(−t/τ)), with v_T = mg/b and τ = m/b.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a22f8d23dc0805', 'les_ba144649758f7f', 3, 'Find terminal velocity for quadratic drag, v_T = √(mg/c).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f121d495e0918d', 'les_ba144649758f7f', 'learn', 1, 'definition', '{"term":"Drag forces","body":"A resistive force opposes motion and grows with speed. At low speeds in a thick fluid, it''s linear: $F = bv$. At higher speeds in air, it''s closer to quadratic: $F = cv^2$. Terminal velocity is reached when drag balances weight, so $a = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_01dd606cca8ab6', 'les_ba144649758f7f', 'learn', 2, 'definition', '{"term":"Solving linear drag","body":"Falling from rest: $m\\frac{dv}{dt} = mg - bv$. Separate variables: $\\int_0^v \\frac{dv''}{g - (b/m)v''} = \\int_0^t dt''$. This gives $v = v_T\\left(1 - e^{-t/\\tau}\\right)$ with $v_T = \\frac{mg}{b}$ and $\\tau = \\frac{m}{b}$. After one $\\tau$, the speed is 63% of terminal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a22f8d23dc0805', 'les_ba144649758f7f', 'learn', 3, 'worked_example', '{"title":"A 0.1 kg ball with b = 0.5 kg/s","steps":[{"latex":"v_T = \\tfrac{0.1(9.8)}{0.5} = 1.96\\ \\text{m/s}","explanation":""},{"latex":"\\tau = \\tfrac{0.1}{0.5} = 0.2\\ \\text{s}","explanation":""},{"latex":"v(0.2) = 1.96(1 - e^{-1}) \\approx 1.24\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_379bbc41e05b0d', 'les_ba144649758f7f', 'learn', 4, 'worked_example', '{"title":"An 80 kg skydiver with quadratic drag, c = 0.25 kg/m","steps":[{"latex":"v_T = \\sqrt{\\tfrac{80(9.8)}{0.25}} = 56\\ \\text{m/s}","explanation":"About 200 km/h."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6c7a2f779899ee', 'les_ba144649758f7f', 'experiment', 5, 'activity', '{"activity":"drag-fall","title":"Approach terminal velocity","params":{"drag":"linear","mass":0.1,"coefficient":0.5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_060870f45394c7', 'les_ba144649758f7f', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Double the mass with linear drag: v_T and τ both double. Switch to quadratic drag and double the mass: v_T grows only by √2."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b6968754b5194d', 'les_ba144649758f7f', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Parachutes raise c to drop terminal speed to about 5 m/s; sediment settling in water and Millikan''s oil-drop experiment use linear drag."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f121d495e0918d', 'les_ba144649758f7f', 1, 'practice', 'numeric', 2, 'A 2 kg block coasts on a surface with drag F = −bv (b = 4 kg/s) from 10 m/s. How long until it slows to 5 m/s? Give two decimal places.', '{"answer":0.35,"tolerance":0.01,"unit":"s"}', '[]', '$v = v_0e^{-bt/m}$, so $t = \frac{m}{b}\ln 2 = 0.5\ln 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_01dd606cca8ab6', 'les_ba144649758f7f', 2, 'practice', 'numeric', 2, 'A 0.01 kg raindrop has linear drag with b = 0.02 kg/s. Find its terminal speed.', '{"answer":4.9,"tolerance":0.01,"unit":"m/s"}', '[]', '$\frac{mg}{b}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a22f8d23dc0805', 'les_ba144649758f7f', 3, 'practice', 'multiple_choice', 2, 'At terminal velocity, the net force is…', '{"choices":["mg","zero","bv","maximum"],"answer":1}', '[]', 'Constant velocity.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_379bbc41e05b0d', 'les_ba144649758f7f', 4, 'review', 'multiple_choice', 3, 'With linear drag, the time to reach 95% of terminal speed is about…', '{"choices":["τ","2τ","3τ","10τ"],"answer":2}', '[]', '$1 - e^{-3} \approx 0.95$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ba144649758f7f', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ba144649758f7f', (SELECT id FROM formulas WHERE slug = 'calculus-mechanics'), 1);

-- Lesson: rotational-inertia-integration
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d24b029296b47b', 'rotational-inertia-integration', 'Rotational inertia by integration', 'Derive rotational inertias of rods, hoops and disks with I = ∫r² dm, handle non-uniform density, and use the parallel-axis theorem.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a48d67a615f2b0', 'les_d24b029296b47b', 1, 'Set up I = ∫r² dm with dm = λ dx or dm = σ dA.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_47ac1b1ac0ede2', 'les_d24b029296b47b', 2, 'Derive I for a rod (center and end) and a solid disk.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9ea2c77ec7a767', 'les_d24b029296b47b', 3, 'Use the parallel-axis theorem, I = I_cm + Md².');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a48d67a615f2b0', 'les_d24b029296b47b', 'learn', 1, 'definition', '{"term":"Definition","body":"For a continuous object, $I = \\int r^2\\,dm$, where $r$ is each piece''s distance from the axis. Choose $dm$ so every bit of it sits at the same $r$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_47ac1b1ac0ede2', 'les_d24b029296b47b', 'learn', 2, 'worked_example', '{"title":"A uniform rod (mass M, length L) about one end","steps":[{"latex":"dm = \\tfrac{M}{L}dx","explanation":""},{"latex":"I = \\int_0^L x^2\\tfrac{M}{L}\\,dx = \\tfrac13 ML^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9ea2c77ec7a767', 'les_d24b029296b47b', 'learn', 3, 'worked_example', '{"title":"A uniform solid disk (mass M, radius R) about its center","steps":[{"latex":"dm = \\sigma(2\\pi r\\,dr),\\ \\sigma = \\tfrac{M}{\\pi R^2}","explanation":"Thin rings of radius r."},{"latex":"I = \\int_0^R r^2\\,\\sigma 2\\pi r\\,dr = \\tfrac{\\pi\\sigma R^4}{2}","explanation":""},{"latex":"I = \\tfrac12 MR^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1f5b5fdbeae806', 'les_d24b029296b47b', 'learn', 4, 'worked_example', '{"title":"A 2 m rod with density λ = 3x kg/m, about x = 0","steps":[{"latex":"I = \\int_0^2 x^2(3x)\\,dx","explanation":""},{"latex":"I = \\tfrac34 x^4\\Big|_0^2 = 12\\ \\text{kg·m}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_65bf24c22fa803', 'les_d24b029296b47b', 'learn', 5, 'definition', '{"term":"Parallel-axis theorem","body":"$I = I_{cm} + Md^2$ for an axis a distance $d$ from a parallel axis through the center of mass. Check: rod about its center, $\\frac{1}{12}ML^2 + M\\left(\\frac L2\\right)^2 = \\frac13ML^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d5f426278e7b56', 'les_d24b029296b47b', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers compute I for turbine blades, flywheels and figure skaters'' body positions; rims are made light because $r^2$ weights them heavily."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a48d67a615f2b0', 'les_d24b029296b47b', 1, 'practice', 'numeric', 2, 'Find I of a 4 kg, 3 m uniform rod about its center.', '{"answer":3,"unit":"kg·m²"}', '[]', '$\frac{1}{12}(4)(9)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_47ac1b1ac0ede2', 'les_d24b029296b47b', 2, 'practice', 'numeric', 3, 'A 1 m rod has λ = 6x kg/m. Find I about x = 0.', '{"answer":1.5,"unit":"kg·m²"}', '[]', '$\int_0^1 6x^3\,dx = 1.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9ea2c77ec7a767', 'les_d24b029296b47b', 3, 'practice', 'numeric', 2, 'A 2 kg disk of radius 0.5 m rotates about a parallel axis through its rim. Find I.', '{"answer":0.75,"unit":"kg·m²"}', '[]', '$\frac12(2)(0.25) + 2(0.25)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1f5b5fdbeae806', 'les_d24b029296b47b', 4, 'review', 'multiple_choice', 3, 'Of these 1 kg, 1 m radius objects, which has the largest I about its central axis?', '{"choices":["solid sphere","solid disk","thin hoop","thin rod along a diameter"],"answer":2}', '[]', 'All of a hoop''s mass is at r = R.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d24b029296b47b', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d24b029296b47b', (SELECT id FROM formulas WHERE slug = 'calculus-rotation'), 1);

-- Lesson: shm-differential-equation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1fc0e2eb58c1ba', 'shm-differential-equation', 'Defining simple harmonic motion', 'Derive the SHM differential equation d²x/dt² = −ω²x from Newton''s second law, verify its sinusoidal solutions, and fit amplitude and phase to initial conditions.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6670d77e53e8ac', 'les_1fc0e2eb58c1ba', 1, 'Show that a linear restoring force gives d²x/dt² = −(k/m)x.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_28098e0c51eda6', 'les_1fc0e2eb58c1ba', 2, 'Verify that x = A cos(ωt + φ) solves it, with ω = √(k/m).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ce1d402f1a120e', 'les_1fc0e2eb58c1ba', 3, 'Find A and φ from the initial position and velocity.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6670d77e53e8ac', 'les_1fc0e2eb58c1ba', 'learn', 1, 'definition', '{"term":"The equation","body":"A mass on a spring obeys $m\\frac{d^2x}{dt^2} = -kx$, so $\\frac{d^2x}{dt^2} = -\\omega^2 x$ with $\\omega = \\sqrt{\\frac km}$. Any system with this form, where acceleration is proportional to minus the displacement, is in simple harmonic motion."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_28098e0c51eda6', 'les_1fc0e2eb58c1ba', 'learn', 2, 'definition', '{"term":"The solution","body":"$x(t) = A\\cos(\\omega t + \\phi)$: differentiating twice gives $-A\\omega^2\\cos(\\omega t + \\phi) = -\\omega^2 x$. ✓ The amplitude $A$ and phase $\\phi$ come from the initial conditions: $x_0 = A\\cos\\phi$ and $v_0 = -A\\omega\\sin\\phi$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ce1d402f1a120e', 'les_1fc0e2eb58c1ba', 'learn', 3, 'worked_example', '{"title":"ω = 5 rad/s, x₀ = 0.1 m, v₀ = 0.5 m/s","steps":[{"latex":"A = \\sqrt{x_0^2 + \\left(\\tfrac{v_0}{\\omega}\\right)^2}","explanation":""},{"latex":"A = \\sqrt{0.01 + 0.01} \\approx 0.141\\ \\text{m}","explanation":""},{"latex":"\\tan\\phi = -\\tfrac{v_0}{\\omega x_0} = -1 \\Rightarrow \\phi = -45°","explanation":""},{"latex":"x(t) = 0.141\\cos(5t - \\tfrac{\\pi}{4})","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c550f88a208ef', 'les_1fc0e2eb58c1ba', 'experiment', 4, 'activity', '{"activity":"spring-oscillator","title":"Watch the solution in motion","params":{"mass":2,"k":50,"amplitude":0.14}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_00dbcd807a3921', 'les_1fc0e2eb58c1ba', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Small vibrations of almost anything near a stable equilibrium (molecules, bridges, quartz crystals in watches) obey this same equation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6670d77e53e8ac', 'les_1fc0e2eb58c1ba', 1, 'practice', 'numeric', 1, 'Find ω for a 2 kg mass on a 50 N/m spring.', '{"answer":5,"unit":"rad/s"}', '[]', '$\sqrt{25}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_28098e0c51eda6', 'les_1fc0e2eb58c1ba', 2, 'practice', 'numeric', 2, 'x(t) = 0.2cos(3t). Find the maximum acceleration.', '{"answer":1.8,"unit":"m/s²"}', '[]', '$A\omega^2 = 0.2(9)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ce1d402f1a120e', 'les_1fc0e2eb58c1ba', 3, 'practice', 'numeric', 3, 'ω = 4 rad/s, released from x₀ = 0 with v₀ = 2 m/s. Find the amplitude.', '{"answer":0.5,"unit":"m"}', '[]', '$A = \frac{v_0}{\omega}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8c550f88a208ef', 'les_1fc0e2eb58c1ba', 4, 'review', 'multiple_choice', 3, 'Which equation describes SHM?', '{"choices":["d²x/dt² = −9x","d²x/dt² = −9","dx/dt = −9x","d²x/dt² = 9x"],"answer":0}', '[]', 'Acceleration proportional to minus displacement.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1fc0e2eb58c1ba', (SELECT id FROM concepts WHERE slug = 'simple-harmonic-motion'));

-- Lesson: torque-cross-product
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_17719429bd899c', 'torque-cross-product', 'Torque', 'Compute torque as the cross product τ = r × F, find its direction with the right-hand rule, and use components.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d2eea4f91e6acb', 'les_17719429bd899c', 1, 'Compute τ = r × F with components.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fdd702d1550568', 'les_17719429bd899c', 2, 'Find torque direction with the right-hand rule.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dc37b1db280926', 'les_17719429bd899c', 3, 'Relate |τ| = rF sin θ to the lever arm and to the force''s perpendicular component.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d2eea4f91e6acb', 'les_17719429bd899c', 'learn', 1, 'definition', '{"term":"Torque as a vector","body":"$\\vec\\tau = \\vec r\\times\\vec F$, where $\\vec r$ runs from the pivot to where the force acts. Its magnitude is $rF\\sin\\theta$. Its direction is along the rotation axis: curl the fingers of your right hand from $\\vec r$ toward $\\vec F$ and your thumb points along $\\vec\\tau$. Counterclockwise in the xy-plane is $+\\hat k$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fdd702d1550568', 'les_17719429bd899c', 'learn', 2, 'definition', '{"term":"Components","body":"For vectors in the xy-plane, $\\tau_z = xF_y - yF_x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dc37b1db280926', 'les_17719429bd899c', 'learn', 3, 'worked_example', '{"title":"r = 2î m and F = 3ĵ N","steps":[{"latex":"\\tau_z = (2)(3) - (0)(0) = 6\\ \\text{N·m}","explanation":"+k̂: counterclockwise."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d23865de1bda6', 'les_17719429bd899c', 'learn', 4, 'worked_example', '{"title":"r = (1, 2) m and F = (3, 1) N","steps":[{"latex":"\\tau_z = (1)(1) - (2)(3) = -5\\ \\text{N·m}","explanation":"−k̂: clockwise."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d1874fc6843c96', 'les_17719429bd899c', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Gyroscopes, bicycle wheels and spinning tops respond to torque vectors in surprising directions; robotics software computes joint torques with cross products."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d2eea4f91e6acb', 'les_17719429bd899c', 1, 'practice', 'numeric', 2, 'r = (3, 0) m, F = (4, 5) N. Find τ_z.', '{"answer":15,"unit":"N·m"}', '[]', '$3(5) - 0(4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fdd702d1550568', 'les_17719429bd899c', 2, 'practice', 'numeric', 2, 'r = (0, 2) m, F = (6, 0) N. Find τ_z.', '{"answer":-12,"unit":"N·m"}', '[]', '$0(0) - 2(6)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dc37b1db280926', 'les_17719429bd899c', 3, 'practice', 'multiple_choice', 2, 'A force acting along the line through the pivot produces…', '{"choices":["maximum torque","zero torque","negative torque","torque equal to F"],"answer":1}', '[]', '$\sin 0° = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5d23865de1bda6', 'les_17719429bd899c', 4, 'review', 'multiple_choice', 3, 'A torque pointing in the +z direction causes rotation in the xy-plane that is…', '{"choices":["clockwise seen from +z","counterclockwise seen from +z","along z","none"],"answer":1}', '[]', 'Right-hand rule.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_17719429bd899c', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_17719429bd899c', (SELECT id FROM formulas WHERE slug = 'calculus-rotation'), 1);
